# MQTT is intentionally implemented with the Python standard library.  The
# packaged SCADA executable must not depend on a separately installed paho
# module, and publishing is kept read-only so IEC-104 remains the source of
# truth for the SCADA UI.
MQTT_STARTED = False
MQTT_LOCK = threading.RLock()
MQTT_LAST_ERROR_LOG = 0.0


def _mqtt_config():
    """Return MQTT settings, with a secure default for mqtt.arita.co.id."""
    defaults = {
        "enabled": True,
        "host": "mqtt.arita.co.id",
        "port": 8883,
        "tls": True,
        "tls_insecure": False,
        "keepalive": 60,
        "publish_interval_seconds": 1.0,
        "topic_prefix": "scada/bont",
        "username": "",
        "password": "",
    }
    try:
        with open(MQTT_CONFIG_PATH, "r", encoding="utf-8-sig") as handle:
            loaded = json.load(handle)
        if isinstance(loaded, dict):
            defaults.update(loaded)
    except Exception:
        pass
    try:
        defaults["port"] = int(defaults.get("port", 8883))
    except (TypeError, ValueError):
        defaults["port"] = 8883
    try:
        defaults["publish_interval_seconds"] = max(
            0.2, float(defaults.get("publish_interval_seconds", 1.0))
        )
    except (TypeError, ValueError):
        defaults["publish_interval_seconds"] = 1.0
    defaults["host"] = str(defaults.get("host", "mqtt.arita.co.id")).strip()
    defaults["topic_prefix"] = str(defaults.get("topic_prefix", "scada/bont")).strip(" /") or "scada/bont"
    defaults["tls"] = bool(defaults.get("tls", defaults["port"] == 8883))
    defaults["tls_insecure"] = bool(defaults.get("tls_insecure", False))
    return defaults


def _mqtt_encode_remaining_length(length):
    encoded = bytearray()
    while True:
        digit = length % 128
        length //= 128
        if length:
            digit |= 0x80
        encoded.append(digit)
        if not length:
            return bytes(encoded)


def _mqtt_utf8(value):
    data = str(value or "").encode("utf-8")
    if len(data) > 65535:
        raise ValueError("MQTT UTF-8 field is too long")
    return struct.pack("!H", len(data)) + data


def _mqtt_recv_exact(sock, size):
    chunks = []
    remaining = int(size)
    while remaining:
        chunk = sock.recv(remaining)
        if not chunk:
            raise ConnectionError("MQTT broker closed the connection")
        chunks.append(chunk)
        remaining -= len(chunk)
    return b"".join(chunks)


class _SimpleMQTTPublisher:
    """Small MQTT 3.1.1 QoS-0 publisher used by the packaged SCADA app."""

    def __init__(self, config, client_id):
        self.config = config
        self.client_id = client_id
        self.sock = None

    def connect(self):
        raw = socket.create_connection(
            (self.config["host"], self.config["port"]), timeout=8.0
        )
        if self.config.get("tls"):
            if self.config.get("tls_insecure"):
                context = ssl._create_unverified_context()
            else:
                context = ssl.create_default_context()
            raw = context.wrap_socket(raw, server_hostname=self.config["host"])
        raw.settimeout(8.0)
        flags = 0x02  # Clean Session.
        username = str(self.config.get("username", "") or "")
        password = str(self.config.get("password", "") or "")
        if username:
            flags |= 0x80
            if password:
                flags |= 0x40
        variable_header = b"\x00\x04MQTT\x04" + bytes([flags]) + struct.pack(
            "!H", int(self.config.get("keepalive", 60))
        )
        payload = _mqtt_utf8(self.client_id)
        if username:
            payload += _mqtt_utf8(username)
            if password:
                payload += _mqtt_utf8(password)
        remaining = variable_header + payload
        packet = b"\x10" + _mqtt_encode_remaining_length(len(remaining)) + remaining
        raw.sendall(packet)
        response = _mqtt_recv_exact(raw, 4)
        if response[:2] != b"\x20\x02" or response[3] != 0:
            raise ConnectionError(
                f"MQTT CONNACK rejected, return_code={response[3] if len(response) > 3 else 'unknown'}"
            )
        self.sock = raw

    def publish(self, topic, payload):
        if self.sock is None:
            raise ConnectionError("MQTT publisher is not connected")
        topic_bytes = str(topic).encode("utf-8")
        body = struct.pack("!H", len(topic_bytes)) + topic_bytes + bytes(payload)
        packet = b"\x30" + _mqtt_encode_remaining_length(len(body)) + body
        self.sock.sendall(packet)

    def close(self):
        if self.sock is None:
            return
        try:
            self.sock.sendall(b"\xE0\x00")
        except Exception:
            pass
        try:
            self.sock.close()
        except Exception:
            pass
        self.sock = None


def _mqtt_runtime_snapshot(local_ip):
    with DATA_LOCK:
        data_store = {str(ip): dict(values) for ip, values in DATA_STORE.items()}
        bay_store = {str(bay): dict(values) for bay, values in BAY_VALUE_STORE.items()}
        vinci_status = {str(ip): bool(value) for ip, value in VINCI_STATUS.items()}
        status_store = [
            {"ip": key[0], "kind": key[1], "key": key[2], "value": value}
            for key, value in STATUS_VALUE_STORE.items()
            if isinstance(key, tuple) and len(key) == 3
        ]
    return {
        "schema": "SCADA-BONT-MQTT-1",
        "generated_at": datetime.datetime.now().isoformat(timespec="milliseconds"),
        "source_ip": str(local_ip or "unknown"),
        "publisher_pid": os.getpid(),
        "rtu": {
            ip: {"online": vinci_status.get(ip, False), "data": values}
            for ip, values in data_store.items()
        },
        "bay": bay_store,
        "status_points": status_store,
    }


def _mqtt_publish_runtime(publisher, config, snapshot):
    prefix = str(config["topic_prefix"]).strip(" /")
    source_ip = str(snapshot.get("source_ip", "unknown"))
    root = f"{prefix}/{source_ip}"
    encoded_snapshot = json.dumps(snapshot, ensure_ascii=False, separators=(",", ":"))
    publisher.publish(f"{root}/snapshot", encoded_snapshot.encode("utf-8"))
    for rtu_ip, item in snapshot.get("rtu", {}).items():
        publisher.publish(
            f"{root}/rtu/{rtu_ip}/data",
            json.dumps(item.get("data", {}), ensure_ascii=False, separators=(",", ":")).encode("utf-8"),
        )
        publisher.publish(
            f"{root}/rtu/{rtu_ip}/status",
            json.dumps(
                {"source_ip": source_ip, "rtu_ip": rtu_ip, "online": item.get("online", False),
                 "generated_at": snapshot.get("generated_at")},
                separators=(",", ":"),
            ).encode("utf-8"),
        )
    publisher.publish(
        f"{root}/bay",
        json.dumps(snapshot.get("bay", {}), ensure_ascii=False, separators=(",", ":")).encode("utf-8"),
    )
    publisher.publish(
        f"{root}/status",
        json.dumps(snapshot.get("status_points", []), ensure_ascii=False, separators=(",", ":")).encode("utf-8"),
    )


def _mqtt_publisher_worker():
    global MQTT_LAST_ERROR_LOG
    publisher = None
    reconnect_delay = 2.0
    last_local_ip = ""
    while True:
        config = _mqtt_config()
        if not config.get("enabled") or not config.get("host"):
            if publisher is not None:
                publisher.close()
                publisher = None
            time.sleep(5.0)
            continue
        try:
            local_ip = _local_scada_ip() or socket.gethostbyname(socket.gethostname())
            client_id = f"scada-bont-{local_ip}-{os.getpid()}"
            if publisher is None or local_ip != last_local_ip:
                if publisher is not None:
                    publisher.close()
                publisher = _SimpleMQTTPublisher(config, client_id)
                publisher.connect()
                last_local_ip = local_ip
                reconnect_delay = 2.0
                _communication_log(
                    local_ip, "MQTT_CONNECTED",
                    f"broker={config['host']}:{config['port']} tls={bool(config.get('tls'))}",
                )
            snapshot = _mqtt_runtime_snapshot(local_ip)
            _mqtt_publish_runtime(publisher, config, snapshot)
            time.sleep(config["publish_interval_seconds"])
        except Exception as exc:
            if publisher is not None:
                publisher.close()
                publisher = None
            now = time.monotonic()
            if now - MQTT_LAST_ERROR_LOG >= 30.0:
                _communication_log(
                    last_local_ip or "MQTT", "MQTT_ERROR",
                    f"{type(exc).__name__}: {exc}",
                )
                MQTT_LAST_ERROR_LOG = now
            time.sleep(reconnect_delay)
            reconnect_delay = min(reconnect_delay * 2.0, 30.0)


def start_mqtt_publisher():
    global MQTT_STARTED
    with MQTT_LOCK:
        if MQTT_STARTED:
            return
        MQTT_STARTED = True
        threading.Thread(
            target=_mqtt_publisher_worker,
            daemon=True,
            name="SCADA-MQTT-Publisher",
        ).start()


def _iec104_connection_mode():
    """Return the configured communication mode."""
    try:
        with open(COMMUNICATION_CONFIG_PATH, "r", encoding="utf-8-sig") as handle:
            config = json.load(handle)
        mode = str(config.get("mode", "auto")).strip().lower()
        master_ip = str(config.get("master_ip", "10.100.163.149")).strip()
    except Exception:
        mode = "auto"
        master_ip = "10.100.163.149"
    return mode if mode in ("master", "peer", "parallel", "parallel_direct", "master_slave") else "parallel_direct"


def _communication_config():
    defaults = {
        "mode": "parallel_direct", "master_ip": "10.100.163.149",
        "peer_ip": "10.100.163.150", "relay_port": 5001,
        "relay_token": "SCADA-BONT-PARALLEL-149-150",
        "node_149_rtus": ["10.100.163.1", "10.100.163.2", "10.100.163.5", "10.100.163.7"],
        "node_150_rtus": ["10.100.163.3", "10.100.163.4", "10.100.163.6", "10.100.163.8"],
    }
    try:
        with open(COMMUNICATION_CONFIG_PATH, "r", encoding="utf-8-sig") as handle:
            loaded = json.load(handle)
        if isinstance(loaded, dict):
            defaults.update(loaded)
    except Exception:
        pass
    return defaults

COMMUNICATION_MODES = (
    "master_slave",
    "parallel",
    "parallel_direct",
    "master",
    "peer",
)


def _validated_ipv4(value, label):
    try:
        address = ipaddress.ip_address(str(value).strip())
    except ValueError as exc:
        raise ValueError(f"{label} must be a valid IPv4 address.") from exc
    if address.version != 4:
        raise ValueError(f"{label} must be an IPv4 address.")
    return str(address)


def _validated_ipv4_list(value, label):
    if isinstance(value, str):
        parts = re.split(r"[,;\\s]+", value.strip())
    elif isinstance(value, (list, tuple, set)):
        parts = list(value)
    else:
        parts = []
    result = []
    for part in parts:
        if str(part).strip():
            address = _validated_ipv4(part, label)
            if address not in result:
                result.append(address)
    return result


def _validate_communication_config(config):
    """Return a normalized, safe CommunicationConfig payload."""
    normalized = dict(config or {})
    mode = str(normalized.get("mode", "")).strip().lower()
    if mode not in COMMUNICATION_MODES:
        raise ValueError(
            "Mode must be one of: " + ", ".join(COMMUNICATION_MODES)
        )
    master_ip = _validated_ipv4(
        normalized.get("master_ip"), "Master IP"
    )
    peer_ip = _validated_ipv4(
        normalized.get("peer_ip"), "Peer IP"
    )
    if master_ip == peer_ip:
        raise ValueError("Master IP and Peer IP must be different.")
    try:
        relay_port = int(str(normalized.get("relay_port", "")).strip())
    except (TypeError, ValueError) as exc:
        raise ValueError("Relay port must be an integer.") from exc
    if not 1 <= relay_port <= 65535:
        raise ValueError("Relay port must be between 1 and 65535.")
    relay_token = str(normalized.get("relay_token", "")).strip()
    if not relay_token:
        raise ValueError("Relay token cannot be empty.")

    node_149 = _validated_ipv4_list(
        normalized.get("node_149_rtus", []), "Node .149 RTU list"
    )
    node_150 = _validated_ipv4_list(
        normalized.get("node_150_rtus", []), "Node .150 RTU list"
    )
    configured_rtus = {str(rtu["ip"]) for rtu in RTU_LIST}
    unknown_rtus = (set(node_149) | set(node_150)) - configured_rtus
    if unknown_rtus:
        raise ValueError(
            "RTU assignments contain unconfigured addresses: "
            + ", ".join(sorted(unknown_rtus))
        )
    overlap = set(node_149) & set(node_150)
    if overlap:
        raise ValueError(
            "RTUs cannot be assigned to both nodes: "
            + ", ".join(sorted(overlap))
        )

    normalized.update({
        "mode": mode,
        "master_ip": master_ip,
        "peer_ip": peer_ip,
        "relay_port": relay_port,
        "relay_token": relay_token,
        "node_149_rtus": node_149,
        "node_150_rtus": node_150,
        "tv_editor_allowed_ips": _validated_ipv4_list(
            normalized.get("tv_editor_allowed_ips", []),
            "TV editor allowed IPs",
        ),
        "description": str(normalized.get("description", "")).strip(),
    })
    return normalized


def _local_scada_ip():
    config = _communication_config()
    candidates = {str(config.get("master_ip", "10.100.163.149")),
                  str(config.get("peer_ip", "10.100.163.150"))}
    try:
        local_ips = set(socket.gethostbyname_ex(socket.gethostname())[2])
        local_ips.update(a[4][0] for a in socket.getaddrinfo(socket.gethostname(), None) if a[4])
    except Exception:
        local_ips = set()
    return next((ip for ip in candidates if ip in local_ips), "")


def _owned_rtu_ips():
    config = _communication_config()
    local_ip = _local_scada_ip()
    if str(config.get("mode", "")).strip().lower() == "master_slave":
        if local_ip == str(config.get("master_ip")):
            return {str(rtu["ip"]) for rtu in RTU_LIST}
        return set()
    if local_ip == str(config.get("master_ip")):
        return set(map(str, config.get("node_149_rtus", [])))
    if local_ip == str(config.get("peer_ip")):
        return set(map(str, config.get("node_150_rtus", [])))
    return set()


def _parallel_peer_ip():
    config = _communication_config()
    local_ip = _local_scada_ip()
    master_ip = str(config.get("master_ip", "10.100.163.149"))
    peer_ip = str(config.get("peer_ip", "10.100.163.150"))
    return peer_ip if local_ip == master_ip else master_ip


# ------------------------------------------------------------------------------
# BIDIRECTIONAL CONFIGURATION SYNC (PC1 <-> PC2)
# ------------------------------------------------------------------------------
# CommunicationConfig.json intentionally stays local.  It identifies the two
# machines and must never be overwritten by ordinary operator edits.
CONFIG_SYNC_STATE_PATH = os.path.join(APP_DIR, "ConfigSyncState.json")
CONFIG_SYNC_LOCK = threading.RLock()


def _config_sync_name_allowed(name):
    """Return True only for operator-editable, portable configuration files."""
    name = os.path.basename(str(name or ""))
    if name in ("UIRealtimeBindings.json", "MonitorTVConfig.json"):
        return True
    return bool(re.fullmatch(r"(?:ListSetting|StatusSetting) .+\.csv", name, re.IGNORECASE))


def _config_sync_files():
    try:
        names = os.listdir(APP_DIR)
    except OSError:
        return []
    return sorted(name for name in names
                  if _config_sync_name_allowed(name)
                  and os.path.isfile(os.path.join(APP_DIR, name)))


def _config_sync_read_state():
    try:
        with open(CONFIG_SYNC_STATE_PATH, "r", encoding="utf-8-sig") as handle:
            state = json.load(handle)
        if isinstance(state, dict) and state.get("schema") == "SCADA-BONT-CONFIG-SYNC-1":
            state.setdefault("clock", 0)
            state.setdefault("files", {})
            return state
    except Exception:
        pass
    return {"schema": "SCADA-BONT-CONFIG-SYNC-1", "clock": 0, "files": {}}


def _config_sync_write_state(state):
    temporary = CONFIG_SYNC_STATE_PATH + ".tmp"
    with open(temporary, "w", encoding="utf-8") as handle:
        json.dump(state, handle, ensure_ascii=False, indent=2, sort_keys=True)
        handle.flush()
        os.fsync(handle.fileno())
    os.replace(temporary, CONFIG_SYNC_STATE_PATH)


def _config_sync_sha256(data):
    return hashlib.sha256(data).hexdigest()


def _config_sync_refresh_local_state():
    """Detect atomic local saves and assign each change a Lamport revision."""
    with CONFIG_SYNC_LOCK:
        state = _config_sync_read_state()
        files = state["files"]
        local_ip = _local_scada_ip() or socket.gethostname()
        changed = False
        for name in _config_sync_files():
            try:
                with open(os.path.join(APP_DIR, name), "rb") as handle:
                    digest = _config_sync_sha256(handle.read())
            except OSError:
                continue
            entry = files.get(name, {})
            if entry.get("sha256") == digest:
                continue
            state["clock"] = max(
                int(state.get("clock", 0) or 0),
                max((int(item.get("revision", 0) or 0)
                     for item in files.values() if isinstance(item, dict)), default=0),
            ) + 1
            files[name] = {
                "revision": state["clock"],
                "origin": local_ip,
                "sha256": digest,
            }
            changed = True
        if changed:
            _config_sync_write_state(state)
        return state


def _config_sync_manifest():
    state = _config_sync_refresh_local_state()
    return {
        "schema": "SCADA-BONT-CONFIG-SYNC-1",
        "node": _local_scada_ip() or socket.gethostname(),
        "files": {name: dict(entry) for name, entry in state.get("files", {}).items()
                  if _config_sync_name_allowed(name) and isinstance(entry, dict)},
    }


def _config_sync_snapshot():
    """Return the current versioned config set for the authenticated peer."""
    manifest = _config_sync_manifest()
    payload_files = {}
    for name, entry in manifest["files"].items():
        try:
            with open(os.path.join(APP_DIR, name), "rb") as handle:
                raw = handle.read()
            if _config_sync_sha256(raw) != entry.get("sha256"):
                continue  # An atomic save raced this snapshot; next poll gets it.
            payload_files[name] = dict(entry, content=base64.b64encode(raw).decode("ascii"))
        except OSError:
            continue
    manifest["files"] = payload_files
    return manifest


def _config_sync_version(entry):
    try:
        return int(entry.get("revision", 0)), str(entry.get("origin", ""))
    except (TypeError, ValueError):
        return 0, ""


def _reload_synced_configuration(changed_names):
    """Reload registries immediately, then refresh Tk widgets on its UI thread."""
    if any(name.lower().startswith("listsetting ") for name in changed_names):
        _load_setting_engine()
    if any(name.lower().startswith("statussetting ") for name in changed_names):
        _load_status_settings()

    app = globals().get("scada_app_instance")
    if app is None or not hasattr(app, "root"):
        return

    def refresh_ui():
        try:
            app.ui_bindings = app._load_ui_bindings()
            app._synchronize_ui_bindings_from_listsettings(force=True)
        except Exception as exc:
            _communication_log("LOCAL", "CONFIG_SYNC_UI_ERROR", str(exc))

    try:
        app.root.after(0, refresh_ui)
    except Exception:
        pass


def _apply_config_sync_snapshot(payload):
    """Apply only strictly newer peer revisions and converge deterministically."""
    if not isinstance(payload, dict) or payload.get("schema") != "SCADA-BONT-CONFIG-SYNC-1":
        raise ValueError("invalid configuration sync payload")
    remote_files = payload.get("files", {})
    if not isinstance(remote_files, dict):
        raise ValueError("invalid configuration file set")

    config = _communication_config()
    valid_origins = {
        str(config.get("master_ip", "")),
        str(config.get("peer_ip", "")),
    }
    changed_names = []
    with CONFIG_SYNC_LOCK:
        state = _config_sync_refresh_local_state()
        local_files = state["files"]
        state_changed = False
        total_bytes = 0
        for name, remote in remote_files.items():
            if not _config_sync_name_allowed(name) or not isinstance(remote, dict):
                continue
            remote_version = _config_sync_version(remote)
            if remote_version[0] <= 0 or remote_version[1] not in valid_origins:
                continue
            if remote_version <= _config_sync_version(local_files.get(name, {})):
                continue
            try:
                raw = base64.b64decode(str(remote.get("content", "")), validate=True)
            except Exception:
                continue
            total_bytes += len(raw)
            if len(raw) > 2 * 1024 * 1024 or total_bytes > 32 * 1024 * 1024:
                raise ValueError("configuration sync payload is too large")
            digest = _config_sync_sha256(raw)
            if digest != str(remote.get("sha256", "")):
                continue

            current = local_files.get(name, {})
            if current.get("sha256") != digest:
                target = os.path.join(APP_DIR, os.path.basename(name))
                temporary = target + ".sync.tmp"
                with open(temporary, "wb") as handle:
                    handle.write(raw)
                    handle.flush()
                    os.fsync(handle.fileno())
                os.replace(temporary, target)
                changed_names.append(name)
            local_files[name] = {
                "revision": remote_version[0],
                "origin": remote_version[1],
                "sha256": digest,
            }
            state["clock"] = max(int(state.get("clock", 0) or 0), remote_version[0])
            state_changed = True
        if state_changed:
            _config_sync_write_state(state)

    if changed_names:
        _reload_synced_configuration(changed_names)
        _communication_log(
            str(payload.get("node", "PEER")), "CONFIG_SYNC_APPLIED",
            "; ".join(sorted(changed_names)),
        )
    return changed_names


def _config_sync_worker():
    """Pull newer configuration from the paired PC about once per second."""
    from urllib.request import Request, urlopen
    config = _communication_config()
    local_ip = _local_scada_ip()
    master_ip = str(config.get("master_ip", "")).strip()
    # In master/slave mode the master is the single source of truth for
    # operator-editable configuration.  A slave may pull from the master, but
    # the master must never pull an older/slave snapshot back and overwrite a
    # just-saved Monitor-TV CT/PT setting.
    is_authoritative_master = (
        str(config.get("mode", "")).strip().lower() == "master_slave"
        and local_ip
        and local_ip == master_ip
    )
    remote_ip = _parallel_peer_ip()
    port = int(config.get("relay_port", 5001))
    token = str(config.get("relay_token", ""))
    headers = {"X-SCADA-Relay-Token": token}
    manifest_url = f"http://{remote_ip}:{port}/ConfigSyncManifest.json"
    snapshot_url = f"http://{remote_ip}:{port}/ConfigSync.json"
    last_error_log = 0.0
    while True:
        try:
            local_state = _config_sync_refresh_local_state()
            request = Request(manifest_url, headers=headers)
            with urlopen(request, timeout=2.0) as response:
                manifest = json.loads(response.read().decode("utf-8"))
            remote_files = manifest.get("files", {}) if isinstance(manifest, dict) else {}
            local_files = local_state.get("files", {})
            has_newer = any(
                _config_sync_version(entry) > _config_sync_version(local_files.get(name, {}))
                for name, entry in remote_files.items() if isinstance(entry, dict)
            )
            if has_newer and not is_authoritative_master:
                request = Request(snapshot_url, headers=headers)
                with urlopen(request, timeout=4.0) as response:
                    snapshot = json.loads(response.read().decode("utf-8"))
                _apply_config_sync_snapshot(snapshot)
        except Exception as exc:
            if time.monotonic() - last_error_log >= 30.0:
                _communication_log(remote_ip, "CONFIG_SYNC_WAITING", str(exc))
                last_error_log = time.monotonic()
        time.sleep(1.0)


def _apply_relay_snapshot(payload):
    """Atomically copy the master's complete runtime state into a peer."""
    if not isinstance(payload, dict) or payload.get("schema") != "SCADA-BONT-RELAY-1":
        raise ValueError("invalid SCADA relay payload")
    with DATA_LOCK:
        owned = _owned_rtu_ips()
        for ip, values in payload.get("data_store", {}).items():
            if str(ip) in owned:
                continue
            if isinstance(values, dict):
                DATA_STORE.setdefault(str(ip), {}).update(values)
        for bay, values in payload.get("bay_store", {}).items():
            # Never overwrite a bay whose RTU is owned locally.
            if str(SETTING_BAY_IP.get(str(bay), "")) in owned:
                continue
            if isinstance(values, dict):
                BAY_VALUE_STORE.setdefault(str(bay), {}).update(values)
        for card, values in payload.get("card_store", {}).items():
            if isinstance(values, dict):
                try:
                    card_idx = int(card)
                    card_ip = next(
                        (str(ip) for idx, _bay, ip, _points in CARD_POINT_MAP if int(idx) == card_idx),
                        ""
                    )
                    if card_ip in owned:
                        continue
                    CARD_VALUE_STORE.setdefault(card_idx, {}).update(values)
                except Exception:
                    continue
        for ip, value in payload.get("vinci_status", {}).items():
            if str(ip) in owned:
                continue
            VINCI_STATUS[str(ip)] = bool(value)
        for item in payload.get("status_store", []):
            if not isinstance(item, dict) or str(item.get("ip", "")) in owned:
                continue
            key = (str(item.get("ip", "")), str(item.get("kind", "")), str(item.get("key", "")))
            try:
                STATUS_VALUE_STORE[key] = int(float(item.get("value", 0)))
            except (TypeError, ValueError):
                continue
        now = time.monotonic()
        now_epoch = time.time()
        for ip in payload.get("data_store", {}):
            if str(ip) not in owned:
                RAW_TIMESTAMP[str(ip)] = now
                _update_communication_diagnostic(
                    ip,
                    {"relay_updates": 1},
                    last_rx_epoch=now_epoch,
                )


def _relay_peer_worker():
    """Read realtime data from PC2 master without opening any RTU socket."""
    from urllib.request import urlopen
    config = _communication_config()
    remote_ip = _parallel_peer_ip()
    port = int(config.get("relay_port", 5001))
    token = str(config.get("relay_token", ""))
    url = f"http://{remote_ip}:{port}/RealtimeSnapshot.json"
    last_ok = 0.0
    while True:
        try:
            from urllib.request import Request
            request = Request(url, headers={"X-SCADA-Relay-Token": token})
            with urlopen(request, timeout=2.0) as response:
                payload = json.loads(response.read().decode("utf-8"))
            _apply_relay_snapshot(payload)
            if time.monotonic() - last_ok > 10.0:
                _communication_log(remote_ip, "RELAY_CONNECTED", url)
            last_ok = time.monotonic()
        except Exception as exc:
            if last_ok and time.monotonic() - last_ok >= 5.0:
                # A relay failure only makes the RTUs owned by the other PC
                # unavailable.  Locally-owned IEC-104 sessions remain valid.
                owned = _owned_rtu_ips()
                with DATA_LOCK:
                    for ip in VINCI_STATUS:
                        if str(ip) not in owned:
                            VINCI_STATUS[ip] = False
                _communication_log(remote_ip, "RELAY_DISCONNECTED", str(exc))
                last_ok = 0.0
        time.sleep(1.0)
