def _embedded_card_points(ip, asdu, ioa):
    try:
        ip = str(ip).strip(); asdu = int(asdu); ioa = int(ioa)
    except Exception:
        return []
    out = []
    for idx, _bay, card_ip, points in CARD_POINT_MAP:
        if str(card_ip).strip() != ip:
            continue
        for physical, pair in points.items():
            if int(pair[0]) == asdu and int(pair[1]) == ioa:
                out.append((idx, physical))
    return out

