def _trend_finite_value(mapping, *keys):
    """Return the first finite numeric value for the requested keys."""
    for key in keys:
        try:
            value = float(mapping.get(key))
        except (TypeError, ValueError):
            continue
        if math.isfinite(value):
            return value
    return None


def _trend_device_definition(device_name):
    """Return the telemetry source and standard trend-variable mapping."""
    source_ip = str(SETTING_BAY_IP.get(device_name, ""))
    if device_name == "Connection Wire I":
        keys = {
            "U": ("W1_Uab",),
            "I": ("W1_Ia",),
            "P": ("W1_P",),
            "Q": ("W1_Q",),
            "f": ("W1_f",),
        }
        source_kind = "rtu"
    elif device_name == "Connection Wire II":
        keys = {
            "U": ("W2_Uab",),
            "I": ("W2_Ia",),
            "P": ("W2_P",),
            "Q": ("W2_Q",),
            "f": ("W2_f",),
        }
        source_kind = "rtu"
    elif device_name in (
        "1# Generator",
        "2# Generator",
        "Voltage Monitoring",
    ):
        keys = {
            "U": ("Uab", "Uab_L", "Uan"),
            "I": ("Ia",),
            "P": ("P", "P_tot"),
            "Q": ("Q",),
            "f": ("f",),
        }
        source_kind = "rtu"
    else:
        keys = {
            "U": ("Uab", "Uab_L", "Uan"),
            "I": ("Ia",),
            "P": ("P", "P_tot"),
            "Q": ("Q",),
            "f": ("f",),
        }
        source_kind = "bay"
    return source_ip, source_kind, keys


def _trend_device_snapshot(device_name, captured_at=None):
    """Build one historian row from the live stores without any UI dependency."""
    source_ip, source_kind, key_map = _trend_device_definition(device_name)
    with DATA_LOCK:
        online = bool(VINCI_STATUS.get(source_ip, False))
        last_update = RAW_TIMESTAMP.get(source_ip)
        fresh = bool(
            online
            and last_update is not None
            and float(last_update) > 0.0
            and (
                time.monotonic() - float(last_update)
                <= NETWORK_DEVICE_STALE_SECONDS
            )
        )
        if source_kind == "bay":
            source_values = dict(BAY_VALUE_STORE.get(device_name, {}))
        else:
            source_values = dict(
                DATA_STORE.get(source_ip, DEFAULT_DATA)
            )

    values = {
        key: (
            _trend_finite_value(source_values, *source_keys)
            if fresh else None
        )
        for key, source_keys in key_map.items()
    }
    has_values = any(value is not None for value in values.values())
    quality = (
        "ONLINE"
        if fresh and has_values
        else "NO DATA"
        if online
        else "OFFLINE"
    )
    if quality != "ONLINE":
        values = {key: None for key in TREND_VALUE_KEYS}
    return {
        "captured_at": int(
            time.time() if captured_at is None else captured_at
        ),
        "device": str(device_name),
        "source_ip": source_ip,
        "quality": quality,
        **values,
    }


def _trend_history_connect():
    """Open and initialize the compact process-trend historian."""
    connection = sqlite3.connect(TREND_HISTORY_DB, timeout=10.0)
    connection.execute(
        """
        CREATE TABLE IF NOT EXISTS trend_samples (
            captured_at INTEGER NOT NULL,
            device TEXT NOT NULL,
            source_ip TEXT NOT NULL,
            quality TEXT NOT NULL,
            voltage REAL,
            current REAL,
            active_power REAL,
            reactive_power REAL,
            frequency REAL,
            PRIMARY KEY (captured_at, device)
        )
        """
    )
    connection.execute(
        """
        CREATE INDEX IF NOT EXISTS idx_trend_device_time
        ON trend_samples (device, captured_at)
        """
    )
    return connection


def _trend_history_log_once(captured_at=None):
    """Persist one sample for every trend device, even when no graph is open."""
    epoch = int(time.time() if captured_at is None else captured_at)
    rows = [
        _trend_device_snapshot(device_name, epoch)
        for device_name in TREND_DEVICES
    ]
    with TREND_HISTORY_LOCK:
        connection = _trend_history_connect()
        try:
            connection.executemany(
                """
                INSERT OR REPLACE INTO trend_samples (
                    captured_at, device, source_ip, quality,
                    voltage, current, active_power,
                    reactive_power, frequency
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                [
                    (
                        row["captured_at"],
                        row["device"],
                        row["source_ip"],
                        row["quality"],
                        row["U"],
                        row["I"],
                        row["P"],
                        row["Q"],
                        row["f"],
                    )
                    for row in rows
                ],
            )
            cutoff = epoch - int(
                TREND_HISTORY_RETENTION_DAYS * 86400
            )
            connection.execute(
                "DELETE FROM trend_samples WHERE captured_at < ?",
                (cutoff,),
            )
            connection.commit()
        finally:
            connection.close()
    return len(rows)


def _trend_history_query(
    device_name, start_epoch, end_epoch, max_points=720,
):
    """Read one device range and optionally aggregate it for screen display."""
    with TREND_HISTORY_LOCK:
        connection = _trend_history_connect()
        try:
            raw_rows = connection.execute(
                """
                SELECT captured_at, source_ip, quality,
                       voltage, current, active_power,
                       reactive_power, frequency
                FROM trend_samples
                WHERE device = ? AND captured_at BETWEEN ? AND ?
                ORDER BY captured_at
                """,
                (
                    str(device_name),
                    int(start_epoch),
                    int(end_epoch),
                ),
            ).fetchall()
        finally:
            connection.close()

    rows = [
        {
            "captured_at": int(row[0]),
            "source_ip": str(row[1]),
            "quality": str(row[2]),
            "U": row[3],
            "I": row[4],
            "P": row[5],
            "Q": row[6],
            "f": row[7],
        }
        for row in raw_rows
    ]
    if not max_points or len(rows) <= int(max_points):
        return rows

    span = max(1, int(end_epoch) - int(start_epoch))
    bucket_seconds = max(
        1, int(math.ceil(span / float(max_points)))
    )
    buckets = {}
    for row in rows:
        bucket = (
            int(row["captured_at"]) // bucket_seconds
        ) * bucket_seconds
        grouped = buckets.setdefault(
            bucket,
            {
                "captured_at": bucket,
                "source_ip": row["source_ip"],
                "qualities": [],
                **{key: [] for key in TREND_VALUE_KEYS},
            },
        )
        grouped["qualities"].append(row["quality"])
        for key in TREND_VALUE_KEYS:
            value = row.get(key)
            if value is not None:
                grouped[key].append(float(value))

    aggregated = []
    for bucket in sorted(buckets):
        grouped = buckets[bucket]
        qualities = grouped.pop("qualities")
        quality = (
            "ONLINE"
            if "ONLINE" in qualities
            else "NO DATA"
            if "NO DATA" in qualities
            else "OFFLINE"
        )
        aggregated.append({
            "captured_at": grouped["captured_at"],
            "source_ip": grouped["source_ip"],
            "quality": quality,
            **{
                key: (
                    sum(grouped[key]) / len(grouped[key])
                    if grouped[key] else None
                )
                for key in TREND_VALUE_KEYS
            },
        })
    return aggregated


def _trend_history_worker():
    """Keep historian sampling independent from all graph windows."""
    while True:
        started = time.monotonic()
        try:
            _trend_history_log_once()
        except Exception as exc:
            print(f"[TREND HISTORIAN] {exc}")
        elapsed = time.monotonic() - started
        time.sleep(
            max(0.25, TREND_HISTORY_INTERVAL - elapsed)
        )


def start_trend_history_logger():
    """Start the single process-wide historian worker."""
    global TREND_HISTORY_STARTED
    if TREND_HISTORY_STARTED:
        return
    TREND_HISTORY_STARTED = True
    threading.Thread(
        target=_trend_history_worker,
        daemon=True,
        name="Process-Trend-Historian",
    ).start()

def _create_actual_history_schema(connection):
    connection.execute(
        """
        CREATE TABLE IF NOT EXISTS actual_samples (
            captured_at INTEGER NOT NULL,
            device_addr TEXT NOT NULL,
            bay_name TEXT NOT NULL,
            physical_name TEXT NOT NULL,
            info_name TEXT NOT NULL,
            value_type TEXT NOT NULL,
            asdu INTEGER NOT NULL,
            ioa INTEGER NOT NULL,
            unit TEXT NOT NULL,
            value REAL,
            quality TEXT NOT NULL,
            PRIMARY KEY (
                captured_at, device_addr, bay_name,
                physical_name, asdu, ioa
            )
        )
        """
    )
    connection.execute(
        """
        CREATE INDEX IF NOT EXISTS idx_actual_time_bay
        ON actual_samples (captured_at, bay_name)
        """
    )


def _actual_history_connect(path=None):
    """Open the one-minute historian containing every active analog point."""
    path = ACTUAL_HISTORY_DB if path is None else path
    parent = os.path.dirname(os.path.abspath(path))
    if parent:
        os.makedirs(parent, exist_ok=True)
    connection = sqlite3.connect(path, timeout=20.0)
    if os.path.abspath(path) == os.path.abspath(ACTUAL_HISTORY_DB):
        connection.execute("PRAGMA journal_mode=WAL")
    _create_actual_history_schema(connection)
    return connection


def _actual_history_log_once(captured_at=None):
    """Persist one one-minute snapshot of every active ListSetting point."""
    epoch = int(time.time() if captured_at is None else captured_at)
    with SETTING_LOCK:
        settings = [dict(row) for row in SETTING_REGISTRY]
    with DATA_LOCK:
        values_by_ip = {
            ip: dict(values) for ip, values in DATA_STORE.items()
        }
        values_by_bay = {
            bay: dict(values) for bay, values in BAY_VALUE_STORE.items()
        }
        online_by_ip = dict(VINCI_STATUS)

    rows = []
    for setting in settings:
        ip = _norm_text(setting.get("Device_Addr"))
        bay = _norm_text(setting.get("Bay_Name"))
        physical = _norm_text(setting.get("Physical_Name"))
        if not ip or not bay or not physical:
            continue
        runtime_name = _runtime_physical_name(setting)
        raw_value = values_by_bay.get(bay, {}).get(
            runtime_name,
            values_by_bay.get(bay, {}).get(
                physical,
                values_by_ip.get(ip, {}).get(
                    runtime_name,
                    values_by_ip.get(ip, {}).get(physical),
                ),
            ),
        )
        try:
            value = float(raw_value)
            if not math.isfinite(value):
                value = None
        except (TypeError, ValueError):
            value = None
        online = bool(online_by_ip.get(ip, False))
        quality = (
            "ONLINE"
            if online and value is not None
            else "NO DATA"
            if online
            else "OFFLINE"
        )
        try:
            asdu = int(setting.get("ASDU_INT"))
        except (TypeError, ValueError):
            asdu = -1
        try:
            ioa = int(setting.get("IOA_INT"))
        except (TypeError, ValueError):
            ioa = -1
        rows.append(
            (
                epoch,
                ip,
                bay,
                physical,
                _norm_text(setting.get("Info_Name")),
                _norm_text(setting.get("Type")),
                asdu,
                ioa,
                _norm_text(setting.get("Unit")),
                value,
                quality,
            )
        )

    cutoff = epoch - int(ACTUAL_HISTORY_RETENTION_DAYS * 86400)
    with ACTUAL_HISTORY_LOCK:
        connection = _actual_history_connect()
        try:
            connection.executemany(
                """
                INSERT OR REPLACE INTO actual_samples (
                    captured_at, device_addr, bay_name, physical_name,
                    info_name, value_type, asdu, ioa, unit, value, quality
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                rows,
            )
            connection.execute(
                "DELETE FROM actual_samples WHERE captured_at < ?",
                (cutoff,),
            )
            connection.commit()
        finally:
            connection.close()
    return len(rows)


def _actual_history_worker():
    while True:
        started = time.monotonic()
        try:
            _actual_history_log_once()
        except Exception as exc:
            print(f"[ACTUAL HISTORIAN] {exc}")
        elapsed = time.monotonic() - started
        time.sleep(max(0.25, ACTUAL_HISTORY_INTERVAL - elapsed))


def start_actual_history_logger():
    """Start the one-minute all-variable historian once per process."""
    global ACTUAL_HISTORY_STARTED
    if ACTUAL_HISTORY_STARTED:
        return
    ACTUAL_HISTORY_STARTED = True
    threading.Thread(
        target=_actual_history_worker,
        daemon=True,
        name="Actual-Value-Historian",
    ).start()


def _backup_sha256_file(path):
    digest = hashlib.sha256()
    with open(path, "rb") as handle:
        while True:
            chunk = handle.read(1024 * 1024)
            if not chunk:
                break
            digest.update(chunk)
    return digest.hexdigest()


def _backup_date_bounds(backup_date):
    start = datetime.datetime.combine(
        backup_date, datetime.time.min,
    )
    end = start + datetime.timedelta(days=1)
    return int(start.timestamp()), int(end.timestamp())


def _backup_daily_directory(backup_date):
    return os.path.join(
        BACKUP_ROOT,
        "Daily",
        f"{backup_date:%Y}",
        f"{backup_date:%m}",
        f"{backup_date:%Y-%m-%d}",
    )


def _backup_daily_archive_path(backup_date):
    return os.path.join(
        _backup_daily_directory(backup_date),
        f"SCADA-BONT-Daily-{backup_date:%Y-%m-%d}.zip",
    )


def _backup_configuration_files():
    fixed_names = {
        "CBZ8000AppData.json",
        "CommunicationConfig.json",
        "MQTTConfig.json",
        "UIRealtimeBindings.json",
        "MonitorTVConfig.json",
        "ConfigSyncState.json",
    }
    try:
        names = os.listdir(APP_DIR)
    except OSError:
        return []
    result = []
    for name in names:
        lower = name.lower()
        is_setting = (
            lower.endswith(".csv")
            and (
                name.startswith("ListSetting ")
                or name.startswith("StatusSetting ")
            )
            and not re.search(
                r"_(fix|backup|bak|old)\.csv$", name, re.IGNORECASE,
            )
        )
        if name not in fixed_names and not is_setting:
            continue
        path = os.path.join(APP_DIR, name)
        if os.path.isfile(path):
            result.append((name, path))
    return sorted(result, key=lambda item: item[0].lower())


def _backup_application_files():
    names = {
        "SCADA_BONT.ico",
        "RUNMONITORING FINAL.png",
        "G1MONITOR.jpg.png",
        "G2MONITOR.jpg.png",
        "SYSTEMCONFIG_DARK.png",
        "AUXILIARY_MATCHED.png",
        "MONITOR V55.html",
    }
    candidates = []
    if getattr(sys, "frozen", False):
        candidates.append(
            (os.path.basename(sys.executable), os.path.abspath(sys.executable))
        )
    else:
        candidates.extend(
            [
                (os.path.basename(__file__), os.path.abspath(__file__)),
                (
                    "cbz8000_device_data.py",
                    os.path.join(APP_DIR, "cbz8000_device_data.py"),
                ),
            ]
        )
    candidates.extend((name, os.path.join(APP_DIR, name)) for name in names)
    return [
        (name, path)
        for name, path in candidates
        if os.path.isfile(path)
    ]


def _backup_write_checksum(path):
    digest = _backup_sha256_file(path)
    checksum_path = path + ".sha256"
    temporary = checksum_path + ".tmp"
    with open(temporary, "w", encoding="ascii", newline="\n") as handle:
        handle.write(f"{digest}  {os.path.basename(path)}\n")
    os.replace(temporary, checksum_path)
    return digest


def _backup_expected_checksum(path):
    try:
        with open(path + ".sha256", "r", encoding="ascii") as handle:
            return handle.readline().strip().split()[0].lower()
    except (OSError, IndexError):
        return ""


def _backup_verify_archive(path):
    if not os.path.isfile(path):
        raise FileNotFoundError(path)
    expected = _backup_expected_checksum(path)
    if not expected:
        raise ValueError("Checksum file is missing or empty.")
    actual = _backup_sha256_file(path)
    if actual.lower() != expected:
        raise ValueError("SHA-256 checksum does not match.")
    with zipfile.ZipFile(path, "r") as archive:
        failed_member = archive.testzip()
        if failed_member:
            raise ValueError(f"Damaged ZIP member: {failed_member}")
        manifest = json.loads(archive.read("manifest.json").decode("utf-8"))
    if manifest.get("status") != "SUCCESS":
        raise ValueError("Backup manifest is not marked SUCCESS.")
    return manifest


def _backup_append_log(
    backup_date,
    trigger,
    status,
    archive="",
    actual_rows=0,
    trend_rows=0,
    config_files=0,
    size_bytes=0,
    sha256="",
    deleted="",
    error="",
):
    os.makedirs(BACKUP_ROOT, exist_ok=True)
    new_file = (
        not os.path.exists(BACKUP_LOG_PATH)
        or os.path.getsize(BACKUP_LOG_PATH) == 0
    )
    with open(
        BACKUP_LOG_PATH, "a", newline="", encoding="utf-8-sig",
    ) as handle:
        writer = csv.writer(handle)
        if new_file:
            writer.writerow(
                [
                    "Timestamp",
                    "Backup_Date",
                    "Trigger",
                    "Status",
                    "Archive",
                    "Actual_Rows",
                    "Trend_Rows",
                    "Config_Files",
                    "Size_Bytes",
                    "SHA256",
                    "Deleted",
                    "Error",
                ]
            )
        writer.writerow(
            [
                datetime.datetime.now().isoformat(timespec="seconds"),
                backup_date.isoformat(),
                trigger,
                status,
                archive,
                actual_rows,
                trend_rows,
                config_files,
                size_bytes,
                sha256,
                deleted,
                error,
            ]
        )


def _backup_actual_rows_for_date(backup_date):
    start_epoch, end_epoch = _backup_date_bounds(backup_date)
    with ACTUAL_HISTORY_LOCK:
        connection = _actual_history_connect()
        try:
            return connection.execute(
                """
                SELECT captured_at, device_addr, bay_name, physical_name,
                       info_name, value_type, asdu, ioa, unit, value, quality
                FROM actual_samples
                WHERE captured_at >= ? AND captured_at < ?
                ORDER BY captured_at, bay_name, physical_name, asdu, ioa
                """,
                (start_epoch, end_epoch),
            ).fetchall()
        finally:
            connection.close()


def _backup_trend_rows_for_date(backup_date):
    start_epoch, end_epoch = _backup_date_bounds(backup_date)
    with TREND_HISTORY_LOCK:
        connection = _trend_history_connect()
        try:
            return connection.execute(
                """
                SELECT captured_at, device, source_ip, quality,
                       voltage, current, active_power,
                       reactive_power, frequency
                FROM trend_samples
                WHERE captured_at >= ? AND captured_at < ?
                ORDER BY captured_at, device
                """,
                (start_epoch, end_epoch),
            ).fetchall()
        finally:
            connection.close()


def _backup_build_daily_database(path, actual_rows, trend_rows, manifest):
    connection = sqlite3.connect(path)
    try:
        _create_actual_history_schema(connection)
        connection.executemany(
            """
            INSERT OR REPLACE INTO actual_samples (
                captured_at, device_addr, bay_name, physical_name,
                info_name, value_type, asdu, ioa, unit, value, quality
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            actual_rows,
        )
        connection.execute(
            """
            CREATE TABLE IF NOT EXISTS trend_samples (
                captured_at INTEGER NOT NULL,
                device TEXT NOT NULL,
                source_ip TEXT NOT NULL,
                quality TEXT NOT NULL,
                voltage REAL,
                current REAL,
                active_power REAL,
                reactive_power REAL,
                frequency REAL,
                PRIMARY KEY (captured_at, device)
            )
            """
        )
        connection.executemany(
            """
            INSERT OR REPLACE INTO trend_samples (
                captured_at, device, source_ip, quality,
                voltage, current, active_power,
                reactive_power, frequency
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            trend_rows,
        )
        connection.execute(
            """
            CREATE TABLE IF NOT EXISTS backup_metadata (
                name TEXT PRIMARY KEY,
                value TEXT NOT NULL
            )
            """
        )
        connection.executemany(
            "INSERT OR REPLACE INTO backup_metadata (name, value) VALUES (?, ?)",
            [
                ("backup_date", str(manifest["backup_date"])),
                ("created_at", str(manifest["created_at"])),
                ("application_version", str(APP_VERSION)),
            ],
        )
        connection.commit()
    finally:
        connection.close()


def _backup_write_actual_csv(path, actual_rows):
    with open(path, "w", newline="", encoding="utf-8-sig") as handle:
        writer = csv.writer(handle)
        writer.writerow(
            [
                "Timestamp",
                "Device Address",
                "Bay",
                "Physical Name",
                "Information Name",
                "Type",
                "ASDU",
                "IOA",
                "Unit",
                "Value",
                "Quality",
            ]
        )
        for row in actual_rows:
            writer.writerow(
                [
                    datetime.datetime.fromtimestamp(row[0]).strftime(
                        "%Y-%m-%d %H:%M:%S"
                    ),
                    *row[1:],
                ]
            )


def _backup_cleanup_application_versions():
    application_root = os.path.join(BACKUP_ROOT, "Application")
    try:
        version_dirs = [
            os.path.join(application_root, name)
            for name in os.listdir(application_root)
            if os.path.isdir(os.path.join(application_root, name))
        ]
    except OSError:
        return []
    version_dirs.sort(
        key=lambda path: os.path.getmtime(path),
        reverse=True,
    )
    deleted = []
    for path in version_dirs[3:]:
        shutil.rmtree(path, ignore_errors=True)
        deleted.append(os.path.basename(path))
    return deleted


def _backup_create_application_snapshot():
    target_dir = os.path.join(BACKUP_ROOT, "Application", APP_VERSION)
    target = os.path.join(
        target_dir,
        f"SCADA-BONT-Application-{APP_VERSION}.zip",
    )
    if os.path.isfile(target):
        try:
            _backup_verify_archive(target)
            return target
        except Exception:
            pass
    os.makedirs(target_dir, exist_ok=True)
    temporary = target + ".tmp"
    files = _backup_application_files()
    members = []
    with zipfile.ZipFile(
        temporary,
        "w",
        compression=zipfile.ZIP_DEFLATED,
        allowZip64=True,
    ) as archive:
        for name, path in files:
            arcname = f"application/{name}"
            archive.write(path, arcname)
            members.append(
                {
                    "name": arcname,
                    "size": os.path.getsize(path),
                    "sha256": _backup_sha256_file(path),
                }
            )
        archive.writestr(
            "manifest.json",
            json.dumps(
                {
                    "status": "SUCCESS",
                    "backup_type": "application",
                    "application_version": APP_VERSION,
                    "created_at": datetime.datetime.now().isoformat(
                        timespec="seconds"
                    ),
                    "members": members,
                },
                ensure_ascii=False,
                indent=2,
            ),
        )
    with zipfile.ZipFile(temporary, "r") as archive:
        failed_member = archive.testzip()
        if failed_member:
            raise ValueError(
                f"Application backup member is damaged: {failed_member}"
            )
    os.replace(temporary, target)
    _backup_write_checksum(target)
    _backup_cleanup_application_versions()
    return target


def _backup_scan_catalog():
    daily_root = os.path.join(BACKUP_ROOT, "Daily")
    records = []
    if not os.path.isdir(daily_root):
        return records
    for directory, _subdirs, filenames in os.walk(daily_root):
        for filename in filenames:
            if not (
                filename.startswith("SCADA-BONT-Daily-")
                and filename.lower().endswith(".zip")
            ):
                continue
            path = os.path.join(directory, filename)
            try:
                with zipfile.ZipFile(path, "r") as archive:
                    manifest = json.loads(
                        archive.read("manifest.json").decode("utf-8")
                    )
                backup_date = datetime.date.fromisoformat(
                    str(manifest["backup_date"])
                )
            except Exception:
                continue
            records.append(
                {
                    "backup_date": backup_date,
                    "path": path,
                    "folder": directory,
                    "size_bytes": os.path.getsize(path),
                    "sha256": _backup_expected_checksum(path),
                    "manifest": manifest,
                }
            )
    records.sort(key=lambda item: item["backup_date"], reverse=True)
    return records


def _backup_cleanup_daily(reference_date):
    cutoff = reference_date - datetime.timedelta(
        days=BACKUP_RETENTION_DAYS - 1
    )
    deleted = []
    daily_root = os.path.realpath(os.path.join(BACKUP_ROOT, "Daily"))
    for record in _backup_scan_catalog():
        if record["backup_date"] >= cutoff:
            continue
        folder = os.path.realpath(record["folder"])
        if folder == daily_root or not folder.startswith(daily_root + os.sep):
            continue
        shutil.rmtree(folder, ignore_errors=True)
        deleted.append(record["backup_date"].isoformat())
    return deleted


def _backup_create_daily(backup_date, trigger="scheduled", force=False):
    """Create one verified daily backup, then enforce the 183-day retention."""
    if isinstance(backup_date, datetime.datetime):
        backup_date = backup_date.date()
    if not isinstance(backup_date, datetime.date):
        raise TypeError("backup_date must be a date")
    with BACKUP_LOCK:
        os.makedirs(BACKUP_ROOT, exist_ok=True)
        _backup_create_application_snapshot()
        target = _backup_daily_archive_path(backup_date)
        if os.path.isfile(target) and not force:
            try:
                _backup_verify_archive(target)
                return next(
                    (
                        record
                        for record in _backup_scan_catalog()
                        if os.path.abspath(record["path"])
                        == os.path.abspath(target)
                    ),
                    None,
                )
            except Exception:
                pass

        os.makedirs(os.path.dirname(target), exist_ok=True)
        temporary = target + ".tmp"
        try:
            actual_rows = _backup_actual_rows_for_date(backup_date)
            trend_rows = _backup_trend_rows_for_date(backup_date)
            config_files = _backup_configuration_files()
            bays = sorted({str(row[2]) for row in actual_rows if row[2]})
            created_at = datetime.datetime.now().isoformat(timespec="seconds")
            manifest = {
                "status": "SUCCESS",
                "backup_type": "daily",
                "backup_date": backup_date.isoformat(),
                "created_at": created_at,
                "application_version": APP_VERSION,
                "retention_days": BACKUP_RETENTION_DAYS,
                "actual_interval_seconds": int(ACTUAL_HISTORY_INTERVAL),
                "actual_rows": len(actual_rows),
                "trend_rows": len(trend_rows),
                "config_files": len(config_files),
                "bays": bays,
                "members": [],
            }
            with tempfile.TemporaryDirectory(
                prefix="scada-backup-",
                dir=BACKUP_ROOT,
            ) as work_dir:
                database_name = (
                    f"SCADA-Daily-{backup_date:%Y-%m-%d}.sqlite3"
                )
                database_path = os.path.join(work_dir, database_name)
                actual_csv_path = os.path.join(
                    work_dir,
                    f"Actual-Values-{backup_date:%Y-%m-%d}.csv",
                )
                _backup_build_daily_database(
                    database_path,
                    actual_rows,
                    trend_rows,
                    manifest,
                )
                _backup_write_actual_csv(actual_csv_path, actual_rows)

                with zipfile.ZipFile(
                    temporary,
                    "w",
                    compression=zipfile.ZIP_DEFLATED,
                    allowZip64=True,
                ) as archive:
                    for member_name, path in (
                        (f"database/{database_name}", database_path),
                        (
                            f"actual/{os.path.basename(actual_csv_path)}",
                            actual_csv_path,
                        ),
                    ):
                        archive.write(path, member_name)
                        manifest["members"].append(
                            {
                                "name": member_name,
                                "size": os.path.getsize(path),
                                "sha256": _backup_sha256_file(path),
                            }
                        )
                    for name, path in config_files:
                        with open(path, "rb") as handle:
                            payload = handle.read()
                        member_name = f"config/{name}"
                        archive.writestr(member_name, payload)
                        manifest["members"].append(
                            {
                                "name": member_name,
                                "size": len(payload),
                                "sha256": hashlib.sha256(payload).hexdigest(),
                            }
                        )
                    archive.writestr(
                        "manifest.json",
                        json.dumps(
                            manifest,
                            ensure_ascii=False,
                            indent=2,
                        ),
                    )
            with zipfile.ZipFile(temporary, "r") as archive:
                failed_member = archive.testzip()
                if failed_member:
                    raise ValueError(
                        f"Daily backup member is damaged: {failed_member}"
                    )
            os.replace(temporary, target)
            digest = _backup_write_checksum(target)
            deleted = _backup_cleanup_daily(backup_date)
            _backup_append_log(
                backup_date,
                trigger,
                "SUCCESS",
                archive=target,
                actual_rows=len(actual_rows),
                trend_rows=len(trend_rows),
                config_files=len(config_files),
                size_bytes=os.path.getsize(target),
                sha256=digest,
                deleted=";".join(deleted),
            )
            return next(
                (
                    record
                    for record in _backup_scan_catalog()
                    if os.path.abspath(record["path"])
                    == os.path.abspath(target)
                ),
                None,
            )
        except Exception as exc:
            try:
                if os.path.exists(temporary):
                    os.remove(temporary)
            except OSError:
                pass
            _backup_append_log(
                backup_date,
                trigger,
                "FAILED",
                archive=target,
                error=str(exc),
            )
            raise


def _backup_actual_csv_member(archive):
    names = [
        name
        for name in archive.namelist()
        if name.startswith("actual/") and name.lower().endswith(".csv")
    ]
    if not names:
        raise ValueError("Actual-value CSV is missing from the backup.")
    return names[0]


def _backup_read_actual_rows(path, bay_name="", limit=5000):
    selected_bay = str(bay_name or "").strip()
    total = 0
    truncated = False
    collected = deque(maxlen=limit) if limit else []
    with zipfile.ZipFile(path, "r") as archive:
        member = _backup_actual_csv_member(archive)
        with archive.open(member, "r") as raw_handle:
            with io.TextIOWrapper(
                raw_handle, encoding="utf-8-sig", newline="",
            ) as text_handle:
                reader = csv.DictReader(text_handle)
                for row in reader:
                    if (
                        selected_bay
                        and selected_bay != "All Bays"
                        and row.get("Bay") != selected_bay
                    ):
                        continue
                    total += 1
                    collected.append(dict(row))
                    if limit and total > limit:
                        truncated = True
    rows = list(collected)
    if limit:
        rows.reverse()
    return rows, total, truncated


def _backup_open_folder():
    os.makedirs(BACKUP_ROOT, exist_ok=True)
    if os.name == "nt":
        os.startfile(BACKUP_ROOT)
    elif sys.platform == "darwin":
        subprocess.Popen(["open", BACKUP_ROOT])
    else:
        subprocess.Popen(["xdg-open", BACKUP_ROOT])


def _daily_backup_worker():
    last_target = None
    while True:
        try:
            target = datetime.date.today() - datetime.timedelta(days=1)
            if target != last_target:
                _backup_create_daily(
                    target,
                    trigger="scheduled",
                    force=False,
                )
                last_target = target
        except Exception as exc:
            print(f"[DAILY BACKUP] {exc}")
        time.sleep(60.0)


def start_daily_backup_worker():
    """Start daily backup catch-up and midnight rollover processing."""
    global BACKUP_STARTED
    if BACKUP_STARTED:
        return
    BACKUP_STARTED = True
    threading.Thread(
        target=_daily_backup_worker,
        daemon=True,
        name="Daily-Backup",
    ).start()


def _xlsx_column_name(index):
    name = ""
    number = int(index)
    while number:
        number, remainder = divmod(number - 1, 26)
        name = chr(65 + remainder) + name
    return name


def _xlsx_text(value):
    text = re.sub(
        r"[\x00-\x08\x0b\x0c\x0e-\x1f]",
        "",
        str(value),
    )
    return escape(text)


def _write_xlsx(path, sheet_name, headers, rows):
    """Write a dependency-free Excel workbook with filters and frozen headers."""
    output_path = os.path.abspath(path)
    if not output_path.lower().endswith(".xlsx"):
        output_path += ".xlsx"
    safe_sheet = re.sub(r"[\[\]:*?/\\]", " ", str(sheet_name)).strip()
    safe_sheet = (safe_sheet or "Data")[:31]
    materialized = [list(row) for row in rows]
    all_rows = [list(headers)] + materialized
    column_count = max(1, len(headers))
    row_count = max(1, len(all_rows))

    widths = []
    for column_index in range(column_count):
        longest = len(str(headers[column_index]))
        for row in materialized[:5000]:
            if column_index < len(row):
                longest = max(longest, len(str(row[column_index])))
        widths.append(min(55, max(10, longest + 2)))

    xml_rows = []
    for row_index, row in enumerate(all_rows, 1):
        cells = []
        for column_index in range(column_count):
            value = row[column_index] if column_index < len(row) else ""
            reference = f"{_xlsx_column_name(column_index + 1)}{row_index}"
            if (
                row_index > 1
                and isinstance(value, (int, float))
                and not isinstance(value, bool)
                and math.isfinite(float(value))
            ):
                cells.append(
                    f'<c r="{reference}" s="2"><v>{float(value)}</v></c>'
                )
            else:
                style = 1 if row_index == 1 else 0
                cells.append(
                    f'<c r="{reference}" s="{style}" t="inlineStr">'
                    f'<is><t xml:space="preserve">{_xlsx_text(value)}</t></is>'
                    "</c>"
                )
        xml_rows.append(
            f'<row r="{row_index}">{"".join(cells)}</row>'
        )

    final_column = _xlsx_column_name(column_count)
    column_xml = "".join(
        f'<col min="{index}" max="{index}" width="{width}" customWidth="1"/>'
        for index, width in enumerate(widths, 1)
    )
    sheet_xml = (
        '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
        '<worksheet xmlns="http://schemas.openxmlformats.org/'
        'spreadsheetml/2006/main">'
        f'<dimension ref="A1:{final_column}{row_count}"/>'
        '<sheetViews><sheetView workbookViewId="0">'
        '<pane ySplit="1" topLeftCell="A2" activePane="bottomLeft" '
        'state="frozen"/></sheetView></sheetViews>'
        '<sheetFormatPr defaultRowHeight="18"/>'
        f"<cols>{column_xml}</cols>"
        f'<sheetData>{"".join(xml_rows)}</sheetData>'
        f'<autoFilter ref="A1:{final_column}{row_count}"/>'
        '</worksheet>'
    )
    styles_xml = (
        '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
        '<styleSheet xmlns="http://schemas.openxmlformats.org/'
        'spreadsheetml/2006/main">'
        '<fonts count="2">'
        '<font><sz val="10"/><name val="Aptos"/></font>'
        '<font><b/><color rgb="FFFFFFFF"/><sz val="10"/>'
        '<name val="Aptos"/></font></fonts>'
        '<fills count="3"><fill><patternFill patternType="none"/></fill>'
        '<fill><patternFill patternType="gray125"/></fill>'
        '<fill><patternFill patternType="solid">'
        '<fgColor rgb="FF16324F"/><bgColor indexed="64"/>'
        '</patternFill></fill></fills>'
        '<borders count="2"><border/>'
        '<border><left style="thin"><color rgb="FFD0D7DE"/></left>'
        '<right style="thin"><color rgb="FFD0D7DE"/></right>'
        '<top style="thin"><color rgb="FFD0D7DE"/></top>'
        '<bottom style="thin"><color rgb="FFD0D7DE"/></bottom>'
        '<diagonal/></border></borders>'
        '<cellStyleXfs count="1"><xf numFmtId="0" fontId="0" '
        'fillId="0" borderId="0"/></cellStyleXfs>'
        '<cellXfs count="3">'
        '<xf numFmtId="0" fontId="0" fillId="0" borderId="1" '
        'xfId="0" applyBorder="1"/>'
        '<xf numFmtId="0" fontId="1" fillId="2" borderId="1" '
        'xfId="0" applyFont="1" applyFill="1" applyBorder="1" '
        'applyAlignment="1"><alignment horizontal="center"/></xf>'
        '<xf numFmtId="2" fontId="0" fillId="0" borderId="1" '
        'xfId="0" applyNumberFormat="1" applyBorder="1"/>'
        '</cellXfs>'
        '<cellStyles count="1"><cellStyle name="Normal" xfId="0" '
        'builtinId="0"/></cellStyles>'
        '</styleSheet>'
    )
    workbook_xml = (
        '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
        '<workbook xmlns="http://schemas.openxmlformats.org/'
        'spreadsheetml/2006/main" xmlns:r="http://schemas.'
        'openxmlformats.org/officeDocument/2006/relationships">'
        f'<sheets><sheet name="{_xlsx_text(safe_sheet)}" sheetId="1" '
        'r:id="rId1"/></sheets></workbook>'
    )
    temporary = output_path + ".tmp"
    with zipfile.ZipFile(
        temporary, "w", compression=zipfile.ZIP_DEFLATED,
    ) as workbook:
        workbook.writestr(
            "[Content_Types].xml",
            '<?xml version="1.0" encoding="UTF-8"?>'
            '<Types xmlns="http://schemas.openxmlformats.org/'
            'package/2006/content-types">'
            '<Default Extension="rels" ContentType="application/vnd.'
            'openxmlformats-package.relationships+xml"/>'
            '<Default Extension="xml" ContentType="application/xml"/>'
            '<Override PartName="/xl/workbook.xml" ContentType="application/'
            'vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/>'
            '<Override PartName="/xl/worksheets/sheet1.xml" ContentType="'
            'application/vnd.openxmlformats-officedocument.spreadsheetml.'
            'worksheet+xml"/>'
            '<Override PartName="/xl/styles.xml" ContentType="application/'
            'vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/>'
            '</Types>',
        )
        workbook.writestr(
            "_rels/.rels",
            '<?xml version="1.0" encoding="UTF-8"?>'
            '<Relationships xmlns="http://schemas.openxmlformats.org/'
            'package/2006/relationships"><Relationship Id="rId1" '
            'Type="http://schemas.openxmlformats.org/officeDocument/2006/'
            'relationships/officeDocument" Target="xl/workbook.xml"/>'
            '</Relationships>',
        )
        workbook.writestr("xl/workbook.xml", workbook_xml)
        workbook.writestr(
            "xl/_rels/workbook.xml.rels",
            '<?xml version="1.0" encoding="UTF-8"?>'
            '<Relationships xmlns="http://schemas.openxmlformats.org/'
            'package/2006/relationships"><Relationship Id="rId1" '
            'Type="http://schemas.openxmlformats.org/officeDocument/2006/'
            'relationships/worksheet" Target="worksheets/sheet1.xml"/>'
            '<Relationship Id="rId2" Type="http://schemas.openxmlformats.'
            'org/officeDocument/2006/relationships/styles" '
            'Target="styles.xml"/></Relationships>',
        )
        workbook.writestr("xl/styles.xml", styles_xml)
        workbook.writestr("xl/worksheets/sheet1.xml", sheet_xml)
    os.replace(temporary, output_path)
    return output_path


