def _default_setting_rows():
    """Build the complete, internally consistent ListSetting CSV set."""
    rows_by_bay = {}

    def add(bay, ip, physical, info_idx, asdu, ioa, typ, formula, unit, coef, ctpt=1.0, add_offset=0.0):
        rows_by_bay.setdefault(bay, []).append({
            "Device_Addr": ip,
            "Bay_Name": bay,
            "Physical_Name": physical,
            "Info_Name": physical,
            "Info_Index": str(info_idx),
            "Type": typ,
            "Min_Save_Mode": "2Minute",
            "ASDU": str(asdu),
            "IOA": "" if ioa is None else str(ioa),
            "Coefficient": str(coef),
            "CTPT": str(ctpt),
            "Tolerance": "0",
            "Alarm_Class": "Warning",
            "UUp_Limit": "1000000",
            "Up_Limit": "1000000",
            "Down_Limit": "-1000000",
            "DDown_Limit": "-1000000",
            "Formula": formula,
            "Add_Offset": str(add_offset),
            "Unit": unit,
        })
    wire_specs = [
        ("W1_Ia", 257, 16385, "Current", "MULTIPLY_CTPT", "A", 0.000183, 500, 0.0),
        ("W1_Uab", 257, 16388, "Voltage", "MULTIPLY_CTPT", "kV", 0.00211438185, 0.10392, 0.0),
        ("W1_Ubc", 257, 16389, "Voltage", "MULTIPLY_CTPT", "kV", 0.00211438185, 0.10392, 0.0),
        ("W1_Uca", 257, 16390, "Voltage", "MULTIPLY_CTPT", "kV", 0.00211438185, 0.10392, 0.0),
        ("W1_P", 257, 16391, "Power", "MULTIPLY_CTPT", "kW", 0.03171386718, 30, 0.0),
        ("W1_Q", 257, 16392, "Power", "MULTIPLY_CTPT", "kVar", 0.03171386718, 30, 0.0),
        ("W1_f", 257, 16393, "Frequency", "FREQUENCY_OFFSET", "Hz", 0.000073242187497, 1, 50.0),
        ("W2_Ia", 513, 16385, "Current", "MULTIPLY_CTPT", "A", 0.000183, 500, 0.0),
        ("W2_Uab", 513, 16388, "Voltage", "MULTIPLY_CTPT", "kV", 0.00211438185, 0.10392, 0.0),
        ("W2_Ubc", 513, 16389, "Voltage", "MULTIPLY_CTPT", "kV", 0.00211438185, 0.10392, 0.0),
        ("W2_Uca", 513, 16390, "Voltage", "MULTIPLY_CTPT", "kV", 0.00211438185, 0.10392, 0.0),
        ("W2_P", 513, 16391, "Power", "MULTIPLY_CTPT", "kW", 0.03171386718, 30, 0.0),
        ("W2_Q", 513, 16392, "Power", "MULTIPLY_CTPT", "kVar", 0.03171386718, 30, 0.0),
        ("W2_f", 513, 16393, "Frequency", "FREQUENCY_OFFSET", "Hz", 0.000073242187497, 1, 50.0),
    ]
    for idx, spec in enumerate(wire_specs, 1):
        add("Connection Wire I" if spec[0].startswith("W1_") else "Connection Wire II",
            "10.100.163.1", *spec[:1], idx, *spec[1:])
    standard = [
        ("Ia", 16385, "Current", "CURRENT_CT", "A", 0.000183, 500),
        ("Ib", 16386, "Current", "CURRENT_CT", "A", 0.000183, 500),
        ("Ic", 16387, "Current", "CURRENT_CT", "A", 0.000183, 500),
        ("Uan", 16388, "Voltage", "PHASE_VOLTAGE", "kV", 0.0036662 * 0.06, 1.0 / 1.732),
        ("Ubn", 16389, "Voltage", "PHASE_VOLTAGE", "kV", 0.0036662 * 0.06, 1.0 / 1.732),
        ("Ucn", 16390, "Voltage", "PHASE_VOLTAGE", "kV", 0.0036662 * 0.06, 1.0 / 1.732),
        ("In", 16391, "Current", "CURRENT_CT", "A", 0.000183, 500),
        ("Uab", 16395, "Voltage", "LINE_VOLTAGE", "kV", 0.0036662, 0.06),
        ("Ubc", 16396, "Voltage", "LINE_VOLTAGE", "kV", 0.0036662, 0.06),
        ("Uca", 16397, "Voltage", "LINE_VOLTAGE", "kV", 0.0036662, 0.06),
        ("P", 16398, "Power", "POWER", "kW", 0.03171366718, 30),
        ("Q", 16399, "Power", "POWER", "kVar", 0.03171366718, 30),
        ("cos", 16400, "Power", "COS", "", 0.000036621097, 1),
        ("P_tot", 16401, "Power", "P_TOTAL", "kW", 0.03171366718, 30),
        ("Uab_L", 16411, "Voltage", "LINE_VOLTAGE", "kV", 0.0036662, 0.06),
        ("Ubc_L", 16412, "Voltage", "LINE_VOLTAGE", "kV", 0.0036662, 0.06),
        ("Uca_L", 16413, "Voltage", "LINE_VOLTAGE", "kV", 0.0036662, 0.06),
        ("IE", 16417, "Current", "ROTOR_IE", "A", 0.01098599999, 1.66),
        ("UE", 16418, "Voltage", "ROTOR_UE", "V", 0.01098599999, 1),
        ("f", 16419, "Frequency", "FREQUENCY_OFFSET", "Hz", 0.0000732421875, 1, 50.0),
    ]
    standard_ips = {f"10.100.163.{n}" for n in range(2, 9)}

    # 14 bottom-card ListSetting CSVs: ONLY Uab, Ia, P, Q.
    # Existing CSV files are authoritative. Defaults are used only to create
    # a missing file; later reloads read the CSV values.
    card_specs = {
        "Ia":  ("Current", "CURRENT_CT", "A",   0.000183,       500.0, 1),
        "Uab": ("Voltage", "LINE_VOLTAGE", "kV", 0.0036662,      0.06, 2),
        "P":   ("Power",   "POWER", "kW",        0.03171366718, 30.0, 3),
        "Q":   ("Power",   "POWER", "kVar",      0.03171366718, 30.0, 4),
    }

    for bay, (ip, points) in CARD_CSV_DEFAULTS.items():
        # Retained only as an engineering reference; runtime never creates CSV.
        for physical in ("Uab", "Ia", "P", "Q"):
            asdu, ioa = points[physical]
            typ, formula, unit, coef, ctpt, info_idx = card_specs[physical]
            add(bay, ip, physical, info_idx, asdu, ioa, typ, formula, unit, coef, ctpt, 0.0)

    for bay, ip in SETTING_BAY_IP.items():
        if ip not in standard_ips or bay in CARD_CSV_DEFAULTS:
            continue
        for idx, spec in enumerate(standard, 1):
            add(bay, ip, spec[0], idx, 1, *spec[1:])

    return rows_by_bay

def _to_float(value, default=0.0):
    try:
        text = str(value).strip().replace(",", ".")
        if text == "":
            return default
        return float(text)
    except Exception:
        return default


FEEDER_BREAKER_ON_COLOR = "#ff2020"
FEEDER_BREAKER_OFF_COLOR = "#14d84a"


def _feeder_breaker_visual(ia_value):
    """Return the feeder breaker state from the IA value shown to two decimals."""
    current = _to_float(ia_value, 0.0)
    if not math.isfinite(current):
        current = 0.0
    displayed_current = round(current, 2)
    active = displayed_current > 0.0
    return (
        displayed_current,
        active,
        FEEDER_BREAKER_ON_COLOR if active else FEEDER_BREAKER_OFF_COLOR,
        "1" if active else "0",
    )



def _norm_text(value):
    return str(value or "").strip()


def _norm_formula(value):
    return _norm_text(value).upper().replace(" ", "").replace("×", "*")


def _setting_filename(bay_name):
    clean = "".join(c for c in str(bay_name) if c.isalnum() or c in (" ", "_", "#")).rstrip()
    return os.path.join(APP_DIR, f"ListSetting {clean}.csv")


def _atomic_write_csv(path, header, rows):
    """Durably replace one editable CSV before any runtime reload reads it."""
    temporary = path + ".tmp"
    try:
        with open(temporary, "w", newline="", encoding="utf-8-sig") as handle:
            writer = csv.writer(handle)
            writer.writerow(list(header))
            writer.writerows(rows)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(temporary, path)
    except Exception:
        try:
            if os.path.exists(temporary):
                os.remove(temporary)
        except OSError:
            pass
        raise


def _status_setting_filename(bay_name="Connection Wire I"):
    clean = "".join(c for c in str(bay_name) if c.isalnum() or c in (" ", "_", "#")).rstrip()
    return os.path.join(APP_DIR, f"StatusSetting {clean}.csv")


def _status_device_ip(value):
    """Translate the status table's short device address (1) to RTU IP .1."""
    text = _norm_text(value)
    if not text:
        return ""
    if "." in text:
        return text
    try:
        return f"10.100.163.{int(float(text))}"
    except Exception:
        return text


def _status_info_ip(info_name):
    """Return the RTU IP encoded by the first two InfoName hex digits.

    Status points use the ``DDYX...`` form, where ``DD`` is the device/IP
    octet.  That encoded address is authoritative; the legacy CSV
    ``Device Addres`` column may contain a bay number instead of an IP.
    """
    decoded = _decode_status_info_name(info_name)
    return str(decoded.get("Device_Addr", "")).strip()


def _decode_status_info_name(info_name):
    """Legacy fallback for old StatusSetting files without decimal ASDU/IOA."""
    text = _norm_text(info_name).upper()
    match = re.fullmatch(r"([0-9A-F]{2})YX([0-9A-F]{4})([0-9A-F]{6})", text)
    if not match:
        return {}
    try:
        device_hex, asdu_hex, ioa_source_hex = match.groups()
        ioa_hex = ioa_source_hex[-2:]
        device_octet = int(device_hex, 16)
        return {
            "Device_Addr": f"10.100.163.{device_octet}",
            "Parsed_ASDU": int(asdu_hex, 16),
            "Parsed_IOA": int(ioa_hex, 16),
            "Device_Hex": device_hex,
            "ASDU_Hex": asdu_hex,
            "IOA_Hex": ioa_hex,
            "IOA_Source_Hex": ioa_source_hex,
        }
    except (TypeError, ValueError):
        return {}


def _load_status_settings():
    """Load rectangle-only status rows without touching the analog registry."""
    rows = []
    for bay_name in STATUS_BAYS:
        path = _status_setting_filename(bay_name)
        try:
            with open(path, "r", newline="", encoding="utf-8-sig") as handle:
                reader = csv.reader(handle)
                next(reader, None)
                for values in reader:
                    if not values or not any(_norm_text(value) for value in values):
                        continue
                    padded = list(values[:len(STATUS_SETTING_KEYS)])
                    padded += [""] * (len(STATUS_SETTING_KEYS) - len(padded))
                    row = dict(zip(STATUS_SETTING_KEYS, padded))
                    info_name = _norm_text(row.get("InfoName"))
                    decoded = _decode_status_info_name(info_name)
                    info_ip = str(decoded.get("Device_Addr", "")).strip()
                    try:
                        explicit_asdu = int(float(_norm_text(row.get("ASDU"))))
                    except Exception:
                        explicit_asdu = None
                    try:
                        explicit_ioa = int(float(_norm_text(row.get("IOA"))))
                    except Exception:
                        explicit_ioa = None
                    try:
                        fallback_ioa = int(float(row.get("Info_Index", "")))
                    except Exception:
                        fallback_ioa = None
                    row.update({
                        "Bay_Name": bay_name,
                        # InfoName's first two hexadecimal digits are the
                        # authoritative RTU/IP address.  Keep the legacy
                        # Device Addres column only as a fallback for old or
                        # malformed rows that have no decodable InfoName.
                        "Device_Addr": info_ip or _status_device_ip(row.get("Device_Addres")),
                        "Physical_Name": _norm_text(row.get("PhysicalName")),
                        "Info_Name": info_name,
                        "Parsed_ASDU": explicit_asdu if explicit_asdu is not None else decoded.get("Parsed_ASDU"),
                        "Parsed_IOA": explicit_ioa if explicit_ioa is not None else decoded.get("Parsed_IOA", fallback_ioa),
                        "Status_IOA": explicit_ioa if explicit_ioa is not None else decoded.get("Parsed_IOA", fallback_ioa),
                        "Device_Hex": decoded.get("Device_Hex", ""),
                        "ASDU_Hex": decoded.get("ASDU_Hex", ""),
                        "IOA_Hex": decoded.get("IOA_Hex", ""),
                        "IOA_Source_Hex": decoded.get("IOA_Source_Hex", ""),
                        "Source_Kind": "rectangle_status_csv",
                    })
                    rows.append(row)
        except (OSError, csv.Error):
            continue
    with STATUS_LOCK:
        STATUS_REGISTRY[:] = rows
    return rows


def _status_binding_for_bay(bay_name, preferred_physical_names):
    """Return a UI binding backed by one authoritative StatusSetting row."""
    with STATUS_LOCK:
        rows = [dict(row) for row in STATUS_REGISTRY]
    if not rows:
        rows = [dict(row) for row in _load_status_settings()]

    bay_key = _norm_text(bay_name).casefold()
    bay_rows = [row for row in rows
                if _norm_text(row.get("Bay_Name")).casefold() == bay_key]
    selected = None
    for physical_name in preferred_physical_names:
        wanted = _norm_text(physical_name).casefold()
        selected = next((row for row in bay_rows
                         if _norm_text(row.get("PhysicalName")).casefold() == wanted), None)
        if selected is not None:
            break
    if selected is None:
        return {}

    return {
        "Device_Addr": selected.get("Device_Addr", ""),
        "Bay_Name": selected.get("Bay_Name", bay_name),
        "Physical_Name": selected.get("PhysicalName", ""),
        "Info_Name": selected.get("InfoName", ""),
        "Info_Index": selected.get("Info_Index", ""),
        "Jian_Ge_Id": selected.get("Jian_Ge_Id", ""),
        "ASDU": selected.get("Parsed_ASDU", ""),
        "IOA": selected.get("Parsed_IOA", ""),
        "Source_Kind": "rectangle_status_csv",
        "SetStr": selected.get("SetStr", ""),
        "ResetStr": selected.get("ResetStr", ""),
        "Reverse": selected.get("Reverse", ""),
    }

# Runtime must use only the existing, operator-approved ListSetting CSV files.
# Missing files are reported by validation; they are never auto-created here.


def _load_all_settings():
    """Load every ListSetting CSV. Missing optional columns are tolerated."""
    rows = []
    try:
        filenames = sorted(
            f for f in os.listdir(APP_DIR)
            if f.startswith("ListSetting ")
            and f.lower().endswith(".csv")
            and not re.search(r"_(fix|backup|bak|old)\.csv$", f, re.IGNORECASE)
        )
    except Exception:
        filenames = []

    for filename in filenames:
        path = os.path.join(APP_DIR, filename)
        try:
            with open(path, "r", newline="", encoding="utf-8-sig") as f:
                reader = csv.DictReader(f)
                if not reader.fieldnames:
                    continue
                for raw in reader:
                    if not raw:
                        continue
                    row = {str(k).strip(): (v if v is not None else "") for k, v in raw.items()}
                    if not _norm_text(row.get("Device_Addr")):
                        # File name remains useful when older CSVs omit Device_Addr.
                        continue
                    if not _norm_text(row.get("Physical_Name")):
                        continue
                    rows.append(row)
        except Exception:
            continue
    return rows


def _load_setting_engine():
    """Build runtime IOA/ASDU registry and dynamically rebuild the 14-card map from CSV."""
    global SETTING_REGISTRY, SETTING_BY_IP_TAG, SETTING_IOA_BY_IP, CARD_POINT_MAP, CARD_BAY_BY_INDEX
    rows = _load_all_settings()
    registry = []
    tag_candidates = {}
    by_tag = {}
    by_ioa = {}

    for row in rows:
        ip = _norm_text(row.get("Device_Addr"))
        physical = _norm_text(row.get("Physical_Name"))
        if not ip or not physical:
            continue
        formula = _norm_formula(row.get("Formula"))
        try:
            ioa_text = _norm_text(row.get("IOA"))
            if not ioa_text:
                # Derived values are valid setting rows but have no protocol IOA.
                if formula in ("DERIVED_P", "DERIVED_Q", "DERIVED_I"):
                    ioa = None
                else:
                    continue
            else:
                ioa = int(float(ioa_text))
        except Exception:
            continue

        try:
            asdu = int(float(_norm_text(row.get("ASDU")) or "1"))
        except Exception:
            asdu = 1

        item = dict(row)
        item["Device_Addr"] = ip
        item["Physical_Name"] = physical
        item["IOA_INT"] = ioa
        item["ASDU_INT"] = asdu
        item["Coefficient_NUM"] = _to_float(row.get("Coefficient"), 1.0)
        item["CTPT_NUM"] = _to_float(row.get("CTPT"), 1.0)
        item["Tolerance_NUM"] = _to_float(row.get("Tolerance"), 0.0)
        item["Add_Offset_NUM"] = _to_float(row.get("Add_Offset"), 0.0)
        registry.append(item)
        # Physical tag lookup is authoritative for engineering/UI calculations.
        tag_candidates.setdefault((ip, physical.strip().lower()), []).append(item)
        # Only protocol-backed settings participate in IOA lookup.
        if ioa is not None:
            by_ioa.setdefault((ip, asdu, ioa), []).append(item)

    # Multiple Bay CSVs may intentionally describe the same physical RTU
    # measurement. Keep every matching row: the same IEC-104 point can feed
    # more than one named bay (for example Generator 2 and its Measure Control
    # Box), and each bay must retain its own engineering formula.
    by_tag = {}
    for key, vals in tag_candidates.items():
        signatures = {(v.get("ASDU_INT"), v.get("IOA_INT")) for v in vals}
        if len(signatures) == 1:
            by_tag[key] = vals[0]

    with SETTING_LOCK:
        SETTING_REGISTRY = registry
        SETTING_BY_IP_TAG = by_tag
        SETTING_IOA_BY_IP = by_ioa

    # IMPORTANT:
    # The CSV is authoritative for the 14 bottom cards.
    # Every reload rebuilds CARD_POINT_MAP from the current CSV values.
    # Therefore changing ASDU/IOA in a ListSetting file takes effect on the
    # next engine reload; the hard-coded defaults are used only when the CSV
    # file does not exist and is auto-created.
    card_order = [
        "11# Circulating Water Pump",
        "12# Circulating Water Pump",
        "13# Circulating Water Pump",
        "1# Feed Water Pump",
        "1# Primary Air Fan",
        "1# Forced draft Fan",
        "1# Induced draft Fan",
        "2# Induced draft Fan",
        "2# Forced draft Fan",
        "2# Primary Air Fan",
        "2# Feed Water Pump",
        "21# Circulating Water Pump",
        "22# Circulating Water Pump",
        "23# Circulating Water Pump",
    ]
    dynamic_cards = []
    for idx, bay in enumerate(card_order, 1):
        bay_rows = [
            r for r in registry
            if _norm_text(r.get("Bay_Name")) == bay
            and _norm_text(r.get("Physical_Name")) in ("Uab", "Ia", "P", "Q")
            and r.get("IOA_INT") is not None
        ]
        # One physical point per card. If duplicate rows exist, use the first
        # exact CSV row consistently rather than silently mixing addresses.
        points = {}
        ip = _norm_text(SETTING_BAY_IP.get(bay, ""))
        for physical in ("Uab", "Ia", "P", "Q"):
            candidates = [r for r in bay_rows if _norm_text(r.get("Physical_Name")) == physical]
            if candidates:
                row = candidates[0]
                ip = _norm_text(row.get("Device_Addr")) or ip
                points[physical] = (int(row["ASDU_INT"]), int(row["IOA_INT"]))
        if len(points) == 4 and ip:
            dynamic_cards.append((idx, bay, ip, points))

    if len(dynamic_cards) == 14:
        CARD_POINT_MAP = dynamic_cards
        CARD_BAY_BY_INDEX = {idx: bay for idx, bay, _ip, _points in CARD_POINT_MAP}
        # Keep existing values by card number; never erase live values merely
        # because a CSV was edited.
        for idx, _bay, _ip, _points in CARD_POINT_MAP:
            CARD_VALUE_STORE.setdefault(idx, {"Uab": 0.0, "Ia": 0.0, "P": 0.0, "Q": 0.0})

    return bool(registry)


# Load CSV settings before communication starts. The bootstrap map remains a
# compatibility fallback only when a particular IOA has no CSV definition.
_load_setting_engine()
_load_status_settings()


def get_ioa_map(ip):
    """Compatibility helper derived from CSV; parser uses IP+ASDU+IOA."""
    result = {}
    with SETTING_LOCK:
        for (key_ip, asdu, ioa), rows in SETTING_IOA_BY_IP.items():
            if key_ip == _norm_text(ip) and len(rows) == 1:
                result[(asdu, ioa)] = _runtime_physical_name(rows[0])
    return result


def _find_settings_for_ioa(ip, asdu, ioa):
    """Find every setting using the full IEC-104 key: IP + ASDU + IOA.

    One IEC-104 point may intentionally feed several settings. Each matching
    row retains its own Formula/Coefficient/CTPT/Add_Offset calculation.
    """
    ip = _norm_text(ip)
    try:
        asdu = int(asdu)
        ioa = int(ioa)
    except Exception:
        return []
    with SETTING_LOCK:
        return list(SETTING_IOA_BY_IP.get((ip, asdu, ioa), []))


def _find_setting_for_ioa(ip, asdu, ioa):
    """Backward-compatible helper returning the first matching setting."""
    matches = _find_settings_for_ioa(ip, asdu, ioa)
    return matches[0] if matches else None

def _runtime_physical_name(setting):
    """
    Runtime tag diambil LANGSUNG dari Physical_Name CSV.

    Contoh CSV:
        W1_Q -> W1_Q
        W2_Q -> W2_Q
        W1_Ubc -> W1_Ubc
        W2_Ubc -> W2_Ubc

    Tidak lagi menentukan W1/W2 berdasarkan range IOA.
    """
    if not setting:
        return None

    physical = _norm_text(setting.get("Physical_Name"))

    if not physical:
        return None

    # Generator 2 and Auxiliary Transformer 2 share one RTU IP.  Keep
    # auxiliary values in separate runtime keys so their Uab/Ia/P/Q values
    # cannot overwrite the Generator 2 values used by the G2 monitor.
    bay = _norm_text(setting.get("Bay_Name"))
    if bay == "1# Auxiliary Transformer":
        return "AUX1_" + physical
    if bay == "2# Auxiliary Transformer":
        return "AUX2_" + physical

    return physical

def _set_raw_value(ip, tag, raw, asdu=None, ioa=None):
    bay_updates = []
    if asdu is not None and ioa is not None:
        with SETTING_LOCK:
            for setting in SETTING_REGISTRY:
                try:
                    if (str(setting.get("Device_Addr", "")).strip() == str(ip).strip() and
                            int(setting.get("ASDU_INT", setting.get("ASDU", -1)) or -1) == int(asdu) and
                            int(setting.get("IOA_INT", setting.get("IOA", -1)) or -1) == int(ioa)):
                        bay = str(setting.get("Bay_Name", "")).strip()
                        physical = _runtime_physical_name(setting)
                        if bay and physical:
                            bay_updates.append((bay, physical))
                except (TypeError, ValueError):
                    continue
    with DATA_LOCK:
        RAW_STORE.setdefault(ip, {})[tag] = raw
        for bay, physical in bay_updates:
            RAW_BAY_VALUE_STORE.setdefault(bay, {})[physical] = raw
        RAW_TIMESTAMP[ip] = time.monotonic()
        if ip == "10.100.163.3" and tag == "Uab":
            print(
        f"[DEBUG G2 Uab] "
        f"ASDU={asdu} IOA={ioa} RAW={raw}"
    )

        # ============================================================
        # 1. PROCESS 14 BOTTOM CARDS
        # ============================================================
        if asdu is not None and ioa is not None:
            for card_idx, physical in _embedded_card_points(ip, asdu, ioa):
                # A single RTU IP serves many bays and every bay reuses the
                # names Uab/Ia/P/Q.  Looking up only (IP, tag) therefore picks
                # an arbitrary bay's coefficient.  Always resolve the exact
                # point which produced this IEC-104 measurement.
                setting = None
                for row in SETTING_REGISTRY:
                    if (
                        _norm_text(row.get("Device_Addr")) == str(ip).strip()
                        and row.get("ASDU_INT") is not None
                        and row.get("IOA_INT") is not None
                        and int(row["ASDU_INT"]) == int(asdu)
                        and int(row["IOA_INT"]) == int(ioa)
                        and _norm_text(row.get("Physical_Name")).lower()
                        == str(physical).lower()
                    ):
                        setting = row
                        break

                if setting is not None:
                    # Use the exact CSV engineering formula.
                    engineering_value = _calculate_formula(
                        float(raw),
                        setting,
                        DATA_STORE.get(
                            str(ip).strip(),
                            DEFAULT_DATA
                        )
                    )
                else:
                    engineering_value = float(raw)

                CARD_VALUE_STORE[card_idx][physical] = float(
                    engineering_value
                )

        # ============================================================
        # 2. PROCESS BAY VALUE
        # ============================================================
        # IMPORTANT:
        # Bay data must NOT depend on _embedded_card_points().
        #
        # Several devices can share the same IP, especially:
        # 10.100.163.4
        #
        # Therefore identify the point using:
        # IP + ASDU + IOA
        # ============================================================
        if asdu is not None and ioa is not None:
            # Update every matching bay, including Auxiliary 2 when another
            # configured bay shares the same IP / ASDU / IOA.
            for point_setting in SETTING_REGISTRY:
                if not (
                    _norm_text(point_setting.get("Device_Addr")) == str(ip).strip()
                    and point_setting.get("ASDU_INT") == int(asdu)
                    and point_setting.get("IOA_INT") == int(ioa)
                ):
                    continue
                point_bay = _norm_text(point_setting.get("Bay_Name"))
                point_physical = _norm_text(point_setting.get("Physical_Name"))
                if not point_bay or not point_physical:
                    continue
                try:
                    bay_value = _calculate_formula(
                        float(raw), point_setting,
                        DATA_STORE.get(str(ip).strip(), DEFAULT_DATA)
                    )
                    if math.isfinite(float(bay_value)):
                        BAY_VALUE_STORE.setdefault(point_bay, {})[point_physical] = float(bay_value)
                        BAY_TIMESTAMP[point_bay] = time.monotonic()
                except Exception:
                    pass


def _safe_formula_eval(expression, variables):
    """Evaluate a small arithmetic expression without allowing Python code."""
    expression = str(expression or "").strip()
    if not expression:
        return None
    tree = ast.parse(expression, mode="eval")
    allowed_bin = (ast.Add, ast.Sub, ast.Mult, ast.Div, ast.Pow)
    allowed_unary = (ast.UAdd, ast.USub)
    def visit(node):
        if isinstance(node, ast.Expression):
            return visit(node.body)
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)):
            return float(node.value)
        if isinstance(node, ast.Name):
            if node.id not in variables:
                raise ValueError(f"Unknown formula variable: {node.id}")
            return float(variables[node.id])
        if isinstance(node, ast.BinOp) and isinstance(node.op, allowed_bin):
            a, b = visit(node.left), visit(node.right)
            if isinstance(node.op, ast.Add): return a + b
            if isinstance(node.op, ast.Sub): return a - b
            if isinstance(node.op, ast.Mult): return a * b
            if isinstance(node.op, ast.Div):
                if abs(b) < 1e-15: raise ZeroDivisionError
                return a / b
            return a ** b
        if isinstance(node, ast.UnaryOp) and isinstance(node.op, allowed_unary):
            value = visit(node.operand)
            return value if isinstance(node.op, ast.UAdd) else -value
        raise ValueError("Unsupported formula expression")
    return visit(tree)


def _calculate_formula(raw, setting, values):
    """Calculate an engineering value exclusively from the CSV setting."""
    raw = float(raw)
    coef = _to_float(setting.get("Coefficient"), 1.0)
    ctpt = _to_float(setting.get("CTPT"), 1.0)
    add_offset = _to_float(setting.get("Add_Offset"), 0.0)
    formula = _norm_formula(setting.get("Formula"))

    # Legacy names remain supported, but their meaning is now explicit and
    # configurable through the CSV instead of hard-coded by IP/tag.
    if formula in ("", "DIRECT", "RAW"):
        return raw
    if formula in ("MULTIPLY", "RAW*COEFFICIENT"):
        return raw * coef
    if formula in ("MULTIPLY_CTPT", "RAW*COEFFICIENT*CTPT", "WIRE_VOLTAGE",
                   "WIRE_CURRENT", "WIRE_POWER", "LINE_VOLTAGE", "PHASE_VOLTAGE",
                   "CURRENT_CT", "POWER", "P_TOTAL", "ROTOR_UE", "ROTOR_IE"):
        return raw * coef * ctpt
    if formula in ("MULTIPLY_ADD", "RAW*COEFFICIENT+ADD_OFFSET"):
        return raw * coef + add_offset
    if formula in ("MULTIPLY_CTPT_ADD", "RAW*COEFFICIENT*CTPT+ADD_OFFSET"):
        return raw * coef * ctpt + add_offset
    if formula == "ADD":
        return raw + add_offset
    if formula == "SUBTRACT":
        return raw - add_offset
    if formula == "FREQUENCY_OFFSET":
        return raw * coef + add_offset
    if formula == "COS":
        return raw * coef
    if formula == "DERIVED_P":
        return values.get("P_tot", values.get("P", 0.0))
    if formula == "DERIVED_Q":
        cosv = float(values.get("cos", 0.0))
        p = float(values.get("P", values.get("P_tot", 0.0)))
        if abs(cosv) < 1e-12:
            return 0.0
        return p * math.tan(math.acos(max(-1.0, min(1.0, cosv))))
    if formula == "DERIVED_I":
        uab = float(values.get("Uab", values.get("Uab_L", 0.0)))
        cosv = float(values.get("cos", 0.0))
        p = float(values.get("P", values.get("P_tot", 0.0)))
        den = math.sqrt(3.0) * uab * cosv
        return 0.0 if abs(den) < 1e-12 else p / den

    # CUSTOM: arithmetic only. Example: RAW*COEFFICIENT*CTPT+ADD_OFFSET
    expr = str(setting.get("Formula", "")).strip()
    if expr.upper().startswith("CUSTOM:"):
        expr = expr.split(":", 1)[1].strip()
    compact = expr.replace("×", "*").replace("÷", "/")
    compact = re.sub(r"\bRaw\b", "RAW", compact, flags=re.IGNORECASE)
    compact = re.sub(r"\bCoefficient\b", "COEFFICIENT", compact, flags=re.IGNORECASE)
    compact = re.sub(r"\bCTPT\b", "CTPT", compact, flags=re.IGNORECASE)
    compact = re.sub(r"\bAdd_Offset\b", "ADD_OFFSET", compact, flags=re.IGNORECASE)
    result = _safe_formula_eval(compact, {
        "RAW": raw, "COEFFICIENT": coef, "CTPT": ctpt, "ADD_OFFSET": add_offset,
    })
    if result is None or not math.isfinite(float(result)):
        raise ValueError("Formula result is not finite")
    return result

def _apply_csv_engineering_once():
    """Apply all CSV formulas once per second to the live data store."""
    global ENGINE_LAST_UPDATE
    now = time.monotonic()
    if now - ENGINE_LAST_UPDATE < ENGINE_UPDATE_INTERVAL:
        return
    ENGINE_LAST_UPDATE = now

    # Reload the CSV registry once per second so a saved setting becomes live
    # without restarting the SCADA application.
    _load_setting_engine()

    with SETTING_LOCK:
        registry = list(SETTING_REGISTRY)

    with DATA_LOCK:
        for rtu in RTU_LIST:
            ip = rtu["ip"]
            raw_values = dict(RAW_STORE.get(ip, {}))
            current_values = dict(DATA_STORE.get(ip, DEFAULT_DATA))
            for setting in registry:
                if setting.get("Device_Addr") != ip:
                    continue
                physical = _runtime_physical_name(setting)
                if not physical:
                    continue
                if _norm_formula(setting.get("Formula")) in ("DERIVED_P", "DERIVED_Q", "DERIVED_I"):
                    continue
                if physical not in raw_values:
                    continue
                try:
                    value = _calculate_formula(float(raw_values[physical]), setting, current_values)
                    if math.isfinite(float(value)):
                        current_values[physical] = float(value)
                except Exception:
                    continue

                if physical == "f":
                    print(
                     f"[FREQ DEBUG] IP={ip} "
                     f"RAW={raw_values[physical]} "
                     f"COEF={setting.get('Coefficient')} "
                     f"FORMULA={setting.get('Formula')} "
                     f"RESULT={value}"
    )

            # Derived variables are calculated after their source variables.
            for setting in registry:
                if setting.get("Device_Addr") != ip:
                    continue
                physical = _runtime_physical_name(setting)
                formula = _norm_formula(setting.get("Formula"))
                if formula not in ("DERIVED_P", "DERIVED_Q", "DERIVED_I"):
                    continue
                try:
                    value = _calculate_formula(0.0, setting, current_values)
                    if math.isfinite(float(value)):
                        current_values[physical] = float(value)
                except Exception:
                    continue

            # Preserve UI keys even when a CSV does not currently contain a row.
            DATA_STORE[ip] = current_values


def _report_safe_filename(name):
    """Build a stable report filename without changing the configured Bay name."""
    clean = str(name or "Report").strip()
    clean = re.sub(r"[^A-Za-z0-9_# -]+", "_", clean)
    clean = clean.replace(" ", "_")
    return os.path.join(APP_DIR, f"Report_{clean}.csv")


def _report_group_settings():
    """Group ListSetting rows by Bay_Name while preserving CSV row order."""
    groups = {}
    with SETTING_LOCK:
        rows = list(SETTING_REGISTRY)
    for row in rows:
        bay = _norm_text(row.get("Bay_Name")) or _norm_text(row.get("Physical_Name")) or "Unknown"
        physical = _norm_text(row.get("Physical_Name"))
        ip = _norm_text(row.get("Device_Addr"))
        if not physical or not ip:
            continue
        groups.setdefault(bay, []).append(row)
    return groups


def _report_unique_columns(rows):
    """Return unique report columns as (label, physical_name, ip)."""
    result = []
    used = set()
    for row in rows:
        physical = _norm_text(row.get("Physical_Name"))
        ip = _norm_text(row.get("Device_Addr"))
        unit = _norm_text(row.get("Unit"))
        if not physical or not ip:
            continue
        base = physical if not unit else f"{physical} [{unit}]"
        label = base
        n = 2
        while label in used:
            label = f"{base} ({n})"
            n += 1
        used.add(label)
        result.append((label, physical, ip))
    return result


def _ensure_report_file(bay_name, rows):
    """Create a report CSV with Date/Time plus the Bay's configured variables."""
    path = _report_safe_filename(bay_name)
    columns = _report_unique_columns(rows)
    header = ["Date", "Time"] + [c[0] for c in columns]
    try:
        if not os.path.exists(path) or os.path.getsize(path) == 0:
            with open(path, "w", newline="", encoding="utf-8-sig") as f:
                csv.writer(f).writerow(header)
        else:
            # Keep existing history. If the current CSV header differs because the
            # setting file changed, do not destroy historical records.
            with open(path, "r", newline="", encoding="utf-8-sig") as f:
                old_header = next(csv.reader(f), [])
            if old_header != header:
                migrated = path + ".new"
                with open(migrated, "w", newline="", encoding="utf-8-sig") as f:
                    csv.writer(f).writerow(header)
                    try:
                        with open(path, "r", newline="", encoding="utf-8-sig") as oldf:
                            old_reader = csv.DictReader(oldf)
                            for old_row in old_reader:
                                out = [old_row.get("Date", ""), old_row.get("Time", "")]
                                for col in header[2:]:
                                    out.append(old_row.get(col, ""))
                                csv.writer(f).writerow(out)
                    except Exception:
                        pass
                os.replace(migrated, path)
    except Exception:
        pass
    return path, columns


def _report_log_once():
    """Record one timestamped engineering snapshot for every configured Bay."""
    groups = _report_group_settings()
    if not groups:
        return
    now = datetime.datetime.now()
    date_text = now.strftime("%Y-%m-%d")
    time_text = now.strftime("%H:%M:%S")
    with DATA_LOCK:
        snapshot = {ip: dict(values) for ip, values in DATA_STORE.items()}
        bay_snapshot = {bay: dict(values) for bay, values in BAY_VALUE_STORE.items()}
    for bay_name, rows in groups.items():
        path, columns = _ensure_report_file(bay_name, rows)
        if not columns:
            continue
        values = [date_text, time_text]
        for _label, physical, ip in columns:
            # Multiple bays share one RTU IP and reuse Uab/Ia/P/Q. Prefer the
            # exact bay store so one pump cannot overwrite another pump's log.
            values.append(
                bay_snapshot.get(bay_name, {}).get(
                    physical,
                    snapshot.get(ip, {}).get(physical, "")
                )
            )
        try:
            with REPORT_LOGGER_LOCK:
                with open(path, "a", newline="", encoding="utf-8-sig") as f:
                    csv.writer(f).writerow(values)
        except Exception:
            continue


def _report_all_variables_once():
    """One explicit row for every active ListSetting point, every minute."""
    path = os.path.join(APP_DIR, "Report_All_Realtime_Variables.csv")
    with SETTING_LOCK:
        rows = [dict(row) for row in SETTING_REGISTRY]
    if not rows:
        return
    now = datetime.datetime.now()
    with DATA_LOCK:
        snapshot = {ip: dict(values) for ip, values in DATA_STORE.items()}
        bay_snapshot = {bay: dict(values) for bay, values in BAY_VALUE_STORE.items()}
    header = ["Date", "Time", "Device_Addr", "Bay_Name", "Physical_Name", "Info_Name", "Type", "ASDU", "IOA", "Unit", "Value"]
    try:
        new_file = not os.path.exists(path) or os.path.getsize(path) == 0
        output = []
        for row in rows:
            ip = str(row.get("Device_Addr", ""))
            bay = str(row.get("Bay_Name", ""))
            physical = str(row.get("Physical_Name", ""))
            value = bay_snapshot.get(bay, {}).get(physical, snapshot.get(ip, {}).get(physical, ""))
            output.append([now.strftime("%Y-%m-%d"), now.strftime("%H:%M:%S"), ip, bay, physical,
                           row.get("Info_Name", ""), row.get("Type", ""), row.get("ASDU", ""),
                           row.get("IOA", ""), row.get("Unit", ""), value])
        with REPORT_LOGGER_LOCK, open(path, "a", newline="", encoding="utf-8-sig") as handle:
            writer = csv.writer(handle)
            if new_file:
                writer.writerow(header)
            writer.writerows(output)
    except Exception:
        pass


def _report_logger_worker():
    """Background logger: exactly one engineering snapshot every two seconds."""
    while True:
        started = time.monotonic()
        try:
            _load_setting_engine()
            _report_log_once()
            _report_all_variables_once()
        except Exception:
            pass
        elapsed = time.monotonic() - started
        time.sleep(max(0.05, REPORT_LOG_INTERVAL - elapsed))


def start_report_logger():
    global REPORT_LOGGER_STARTED
    if REPORT_LOGGER_STARTED:
        return
    REPORT_LOGGER_STARTED = True
    threading.Thread(target=_report_logger_worker, daemon=True, name="Report-Data-Logger").start()


def scale_value(ip, tag, raw):
    """Return the CSV-defined engineering value only.

    ListSetting CSV is authoritative. If no setting exists, keep the raw value
    so an unmapped point cannot silently inherit an old hard-coded formula.
    """
    setting = SETTING_BY_IP_TAG.get((ip, str(tag).strip().lower()))
    if setting is None:
        return float(raw)
    return _calculate_formula(float(raw), setting, DATA_STORE.get(ip, DEFAULT_DATA))


def _decode_raw_value(type_id, payload):
    """Decode IEC-104 measurement payload without applying engineering scaling."""
    if type_id == 13:
        if len(payload) < 4:
            raise ValueError("float payload too short")
        return struct.unpack("<f", payload[:4])[0]
    if len(payload) < 2:
        raise ValueError("16-bit payload too short")
    # EXACT Tificodev behavior: signed 16-bit for IEC104 types 9/11.
    return struct.unpack("<h", payload[:2])[0]

def _communication_log(ip, event, detail=""):
    """Write actionable communication events without flooding the log."""
    stamp = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    clean_detail = str(detail).replace("\n", " ").replace("\r", " ").replace(",", ";")
    line = f"{stamp},{ip},{event},{clean_detail}\n"
    try:
        with COMM_LOG_LOCK:
            with open(os.path.join(APP_DIR, "CommunicationLog.csv"), "a", encoding="utf-8") as handle:
                if handle.tell() == 0:
                    handle.write("Timestamp,IP,Event,Detail\n")
                handle.write(line)
    except Exception:
        pass


def _set_status_raw_value(ip, asdu, ioa, raw):
    """Store one digital IEC value for rectangle-only status bindings."""
    with STATUS_LOCK:
        rows = list(STATUS_REGISTRY)
    matches = []
    for row in rows:
        if _norm_text(row.get("Device_Addr")) != _norm_text(ip):
            continue
        parsed_asdu = row.get("Parsed_ASDU")
        parsed_ioa = row.get("Parsed_IOA")
        if parsed_asdu is not None and parsed_ioa is not None:
            try:
                if int(parsed_asdu) == int(asdu) and int(parsed_ioa) == int(ioa):
                    matches.append(row)
            except Exception:
                pass
            continue

        # Legacy fallback for manually entered rows whose InfoName does not
        # follow the DDYXAAAAIIIIII hexadecimal convention.
        candidates = set()
        for value in (row.get("Status_IOA"), row.get("Info_Index")):
            try:
                candidates.add(int(float(value)))
            except Exception:
                pass
        if int(ioa) not in candidates:
            continue
        try:
            if int(float(row.get("Jian_Ge_Id"))) == int(asdu):
                matches.append(row)
        except Exception:
            matches.append(row)
    if not matches:
        return
    with DATA_LOCK:
        for row in matches:
            info_name = _norm_text(row.get("InfoName"))
            physical = _norm_text(row.get("PhysicalName"))
            index = _norm_text(row.get("Info_Index"))
            # Status IEC-104 bersifat diskret. Simpan sebagai integer agar
            # snapshot/relay mengirim 0, 1 (atau 2/3 untuk double point),
            # bukan angka rekayasa seperti 0.0.
            status_raw = int(raw)
            if info_name:
                STATUS_VALUE_STORE[(str(ip), "info", info_name)] = status_raw
            if physical:
                STATUS_VALUE_STORE[(str(ip), "physical", physical)] = status_raw
            if index:
                STATUS_VALUE_STORE[(str(ip), "index", index)] = status_raw


def _parse_status_iec104_objects(ip, asdu_addr, type_id, vsq, frame):
    """Decode IEC-104 single/double-point information for rectangle status."""
    is_sequence = bool(vsq & 0x80)
    count = vsq & 0x7F
    if count <= 0:
        return
    timed = type_id in (30, 31)
    payload_size = 8 if timed else 1  # SIQ/DIQ plus optional CP56Time2a.

    def status_value(byte_value):
        if type_id in (3, 31):
            return int(byte_value) & 0x03
        return int(byte_value) & 0x01

    if is_sequence:
        if len(frame) < 15:
            return
        ioa_start = frame[12] | (frame[13] << 8) | (frame[14] << 16)
        offset = 15
        for index in range(count):
            if offset + payload_size > len(frame):
                break
            _set_status_raw_value(ip, asdu_addr, ioa_start + index, status_value(frame[offset]))
            offset += payload_size
        return

    offset = 12
    for _ in range(count):
        if offset + 3 + payload_size > len(frame):
            break
        ioa = frame[offset] | (frame[offset + 1] << 8) | (frame[offset + 2] << 16)
        _set_status_raw_value(ip, asdu_addr, ioa, status_value(frame[offset + 3]))
        offset += 3 + payload_size


def _parse_iec104_frame(ip, frame, sock, rx_state):
    """
    Decode IEC-104 measurement frames.

    IMPORTANT:
    - RTU1 tidak lagi dibatasi hanya ASDU 257.
    - ASDU + IOA dicocokkan ke ListSetting CSV.
    - Physical_Name dari CSV digunakan sebagai tag runtime.
    - W1/W2 dipisahkan oleh _runtime_physical_name().
    - Jika CSV tidak memiliki mapping, parser masih memakai
      IOA_MAP legacy sebagai fallback.
    """

    if len(frame) < 6:
        return

    # U-format link management. TESTFR must be confirmed or some RTUs close
    # an otherwise healthy, idle connection.
    control_0 = frame[2]
    if control_0 & 0x03 == 0x03:
        if control_0 == 0x43:  # TESTFR act
            sock.sendall(bytes.fromhex("68 04 83 00 00 00"))
        elif control_0 == 0x83:  # TESTFR con
            rx_state["testfr_pending_since"] = None
        return

    # S-format frames carry acknowledgements only.
    if control_0 & 0x03 == 0x01:
        return

    # ---------------------------------------------------------
    # IEC-104 ACK
    # ---------------------------------------------------------
    if (frame[2] & 0x01) == 0:
        remote_ns = ((frame[3] << 8) | frame[2]) >> 1
        rx_state["next_rx_seq"] = (remote_ns + 1) & 0x7FFF
        rx_state["rx_count"] += 1

        if rx_state["rx_count"] % 4 == 0:
            send_s_frame(sock, rx_state["next_rx_seq"])

    # Minimal frame untuk membaca ASDU
    if len(frame) < 15:
        return

    # ---------------------------------------------------------
    # HEADER IEC-104
    # ---------------------------------------------------------
    type_id = frame[6]
    vsq = frame[7]

    # ASDU address
    asdu_addr = frame[10] | (frame[11] << 8)

    # Digital status types feed only rectangle bindings.  They never enter
    # the analog scaling/report/alarm registries.
    if type_id in (1, 3, 30, 31):
        _parse_status_iec104_objects(ip, asdu_addr, type_id, vsq, frame)
        return

    # ---------------------------------------------------------
    # SUPPORTED ANALOG MEASUREMENT TYPES
    # ---------------------------------------------------------
    if type_id not in (9, 11, 13):
        return

    # ---------------------------------------------------------
    # CSV MAPPING
    # ---------------------------------------------------------
    #
    # CSV sekarang menjadi sumber utama:
    #
    # Device_Addr
    # ASDU
    # IOA
    # Physical_Name
    #
    # Contoh:
    #
    # IP       = 10.100.163.1
    # ASDU     = 258
    # IOA      = 16397
    # Physical = Q
    #
    # kemudian _runtime_physical_name()
    # akan menghasilkan:
    #
    # W2_Q
    #
    # ---------------------------------------------------------

    ioa_map = IOA_MAP_RTU1 if ip == "10.100.163.1" else IOA_MAP_STANDARD

    is_sequence = bool(vsq & 0x80)
    count = vsq & 0x7F

    if count <= 0:
        return

    # ---------------------------------------------------------
    # PROCESS DATA
    # ---------------------------------------------------------
    with DATA_LOCK:

        RAW_STORE.setdefault(ip, {})

        # =====================================================
        # SEQUENCE OF IOA
        # =====================================================
        if is_sequence:

            if len(frame) < 15:
                return

            ioa_start = (
                frame[12]
                | (frame[13] << 8)
                | (frame[14] << 16)
            )

            offset = 15

            for i in range(count):

                # ---------------------------------------------
                # TYPE 9 / 11 = SIGNED INT16 + QUALITY
                # ---------------------------------------------
                if type_id in (9, 11):

                    if offset + 3 > len(frame):
                        break

                    raw_val = struct.unpack(
                        "<h",
                        frame[offset:offset + 2]
                    )[0]

                    offset += 3

                # ---------------------------------------------
                # TYPE 13 = FLOAT32 + QUALITY
                # ---------------------------------------------
                else:

                    if offset + 5 > len(frame):
                        break

                    raw_val = struct.unpack(
                        "<f",
                        frame[offset:offset + 4]
                    )[0]

                    offset += 5

                ioa = ioa_start + i
                address_key = (str(ip).strip(), int(asdu_addr), int(ioa))
                RAW_ADDRESS_STORE[address_key] = float(raw_val)
                RAW_ADDRESS_TIMESTAMP[address_key] = time.monotonic()

                # ---------------------------------------------
                # CSV FIRST
                # ---------------------------------------------
                matching_settings = _find_settings_for_ioa(
                    ip,
                    asdu_addr,
                    ioa
                )
                if not matching_settings:
                    # CSV is authoritative. Never fall back to a shared IOA map,
                    # because the same IOA may exist under different ASDUs.
                    continue

                for setting in matching_settings:
                    tag = _runtime_physical_name(setting)
                    if not tag:
                        continue
                    _set_raw_value(
                        ip, tag, raw_val, asdu=asdu_addr, ioa=ioa
                    )

                # DEBUG
                if ip == "10.100.163.1":
                    print(
                        f"[IEC104 CSV] "
                        f"IP={ip} "
                        f"ASDU={asdu_addr} "
                        f"IOA={ioa} "
                        f"TAG={tag} "
                        f"RAW={raw_val}"
                    )

        # =====================================================
        # INDIVIDUAL IOA
        # =====================================================
        else:

            offset = 12

            for _ in range(count):

                # ---------------------------------------------
                # TYPE 9 / 11
                # ---------------------------------------------
                if type_id in (9, 11):

                    if offset + 6 > len(frame):
                        break

                    ioa = (
                        frame[offset]
                        | (frame[offset + 1] << 8)
                        | (frame[offset + 2] << 16)
                    )

                    raw_val = struct.unpack(
                        "<h",
                        frame[offset + 3:offset + 5]
                    )[0]

                    offset += 6

                # ---------------------------------------------
                # TYPE 13
                # ---------------------------------------------
                else:

                    if offset + 8 > len(frame):
                        break

                    ioa = (
                        frame[offset]
                        | (frame[offset + 1] << 8)
                        | (frame[offset + 2] << 16)
                    )

                    raw_val = struct.unpack(
                        "<f",
                        frame[offset + 3:offset + 7]
                    )[0]

                    offset += 8
                address_key = (str(ip).strip(), int(asdu_addr), int(ioa))
                RAW_ADDRESS_STORE[address_key] = float(raw_val)
                RAW_ADDRESS_TIMESTAMP[address_key] = time.monotonic()

                # ---------------------------------------------
                # CSV FIRST
                # ---------------------------------------------
                matching_settings = _find_settings_for_ioa(
                    ip,
                    asdu_addr,
                    ioa
                )
                if not matching_settings:
                    # CSV is authoritative. Never fall back to a shared IOA map,
                    # because the same IOA may exist under different ASDUs.
                    continue

                for setting in matching_settings:
                    tag = _runtime_physical_name(setting)
                    if not tag:
                        continue
                    _set_raw_value(
                        ip, tag, raw_val, asdu=asdu_addr, ioa=ioa
                    )

                # DEBUG
                if ip == "10.100.163.1":
                    print(
                        f"[IEC104 CSV] "
                        f"IP={ip} "
                        f"ASDU={asdu_addr} "
                        f"IOA={ioa} "
                        f"TAG={tag} "
                        f"RAW={raw_val}"
                    )


def iec104_client(rtu_info):
    ip = rtu_info["ip"]
    port = rtu_info["port"]
    reconnect_delay = VINCI_RECONNECT_DELAY
    while True:
        _update_communication_diagnostic(
            ip, {"connect_attempts": 1}
        )
        sock = None
        connected_at = None
        try:
            sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            sock.settimeout(VINCI_CONNECT_TIMEOUT)
            sock.setsockopt(socket.SOL_SOCKET, socket.SO_KEEPALIVE, 1)
            # Force the IEC-104 session to use this computer's SCADA NIC.
            # PC .149 and PC .150 therefore create independent sessions with
            # different source addresses even on multi-NIC Windows systems.
            source_ip = _local_scada_ip()
            if source_ip:
                sock.bind((source_ip, 0))
            try:
                # Windows: keepalive enabled after 30 s, then probe every 5 s.
                sock.ioctl(socket.SIO_KEEPALIVE_VALS, (1, 30000, 5000))
            except (AttributeError, OSError):
                pass
            sock.connect((ip, port))
            sock.settimeout(VINCI_SOCKET_TIMEOUT)
            connected_at = time.monotonic()
            with DATA_LOCK:
                VINCI_STATUS[ip] = True
            _update_communication_diagnostic(
                ip,
                {"connections": 1},
                last_connected_epoch=time.time(),
                last_error="",
                last_error_epoch=None,
            )
            _communication_log(ip, "CONNECTED", f"port={port}")

            send_startda(sock)
            # EXACT GI packet used by SCADATIFICODEV02.py.
            send_gi(sock)

            buffer = b""
            rx_state = {"rx_count": 0, "next_rx_seq": 0, "testfr_pending_since": None}
            last_rx = time.monotonic()

            while True:
                try:
                    data = sock.recv(2048)
                except socket.timeout:
                    now = time.monotonic()
                    pending_since = rx_state.get("testfr_pending_since")
                    if pending_since is not None:
                        if now - pending_since >= VINCI_TESTFR_TIMEOUT:
                            raise TimeoutError("TESTFR confirmation timeout")
                    elif now - last_rx >= VINCI_TESTFR_INTERVAL:
                        sock.sendall(bytes.fromhex("68 04 43 00 00 00"))
                        rx_state["testfr_pending_since"] = now
                    continue
                if not data:
                    raise ConnectionError("IEC-104 peer closed connection")
                last_rx = time.monotonic()
                # Any received traffic proves the peer is alive.
                rx_state["testfr_pending_since"] = None
                _update_communication_diagnostic(
                    ip,
                    {"rx_bytes": len(data)},
                    last_rx_epoch=time.time(),
                )
                buffer += data

                while len(buffer) >= 2:
                    if buffer[0] != 0x68:
                        buffer = buffer[1:]
                        continue
                    frame_len = buffer[1] + 2
                    if frame_len < 6:
                        buffer = buffer[2:]
                        continue
                    if len(buffer) < frame_len:
                        break
                    frame = buffer[:frame_len]
                    buffer = buffer[frame_len:]
                    _update_communication_diagnostic(
                        ip, {"rx_frames": 1}
                    )
                    _parse_iec104_frame(ip, frame, sock, rx_state)

            reconnect_delay = VINCI_RECONNECT_DELAY
        except Exception as exc:
            _communication_log(ip, "DISCONNECTED", f"{type(exc).__name__}: {exc}")
            increments = {"errors": 1}
            if connected_at is not None:
                increments["disconnects"] = 1
            _update_communication_diagnostic(
                ip,
                increments,
                last_error=f"{type(exc).__name__}: {exc}"[:240],
                last_error_epoch=time.time(),
            )
        finally:
            with DATA_LOCK:
                VINCI_STATUS[ip] = False
            try:
                if sock:
                    sock.shutdown(socket.SHUT_RDWR)
            except Exception:
                pass
            try:
                if sock:
                    sock.close()
            except Exception:
                pass
            # Back off when an RTU is busy or accepts only one client.
            stable = connected_at is not None and time.monotonic() - connected_at >= 30.0
            if stable:
                reconnect_delay = VINCI_RECONNECT_DELAY
            time.sleep(reconnect_delay)
            if not stable:
                reconnect_delay = min(reconnect_delay * 2.0, VINCI_RECONNECT_MAX_DELAY)

def send_startda(sock):
    sock.sendall(bytes.fromhex("68 04 07 00 00 00"))


def send_gi(sock):
    # EXACT GI packet from SCADATIFICODEV02.py
    gi = bytes.fromhex("68 0E 00 00 00 00 64 01 06 00 01 08 00 00 00")
    sock.sendall(gi)


def send_s_frame(sock, rx_num):
    nr = (rx_num << 1).to_bytes(2, byteorder="little")
    s_frame = bytes([0x68, 0x04, 0x01, 0x00, nr[0], nr[1]])
    try:
        sock.sendall(s_frame)
    except Exception:
        pass


