    def _setup_responsive_theme(self):
        """Professional SCADA typography: responsive geometry, stable readable controls."""
        style = ttk.Style(self.root)
        try:
            style.theme_use("clam")
        except Exception:
            pass
        style.configure("Treeview", font=("Segoe UI", 10), rowheight=28)
        style.configure("Treeview.Heading", font=("Segoe UI", 10, "bold"), padding=(6, 7))
        style.configure("TCombobox", font=("Segoe UI", 10))
        style.configure("TButton", font=("Segoe UI", 10, "bold"), padding=(10, 6))
        style.configure("TNotebook.Tab", font=("Segoe UI", 10, "bold"), padding=(12, 7))

    def _responsive_button(self, parent, **kwargs):
        """Create a readable button with comfortable touch/click target."""
        kwargs.setdefault("font", ("Segoe UI", 10, "bold"))
        kwargs.setdefault("padx", 10)
        kwargs.setdefault("pady", 5)
        kwargs.setdefault("height", 1)
        return tk.Button(parent, **kwargs)

    def _bind_mousewheel(self, widget):
        """Scroll Treeview/Paned content with the mouse wheel without showing a scrollbar."""
        def _wheel(event):
            try:
                widget.yview_scroll(int(-1 * (event.delta / 120)), "units")
            except Exception:
                pass
            return "break"
        widget.bind("<MouseWheel>", _wheel, add="+")
        widget.bind("<Button-4>", lambda e: (widget.yview_scroll(-3, "units"), "break")[1], add="+")
        widget.bind("<Button-5>", lambda e: (widget.yview_scroll(3, "units"), "break")[1], add="+")

    def _fit_tree_columns(self, tree, columns, minimums=None, weights=None):
        """Make Treeview columns fill the available width; no horizontal scrollbar."""
        minimums = minimums or [70] * len(columns)
        weights = weights or [1] * len(columns)
        def resize(_event=None):
            try:
                total = max(tree.winfo_width() - 4, 100)
                total_weight = float(sum(weights))
                for i, col in enumerate(columns):
                    width = max(minimums[i], int(total * weights[i] / total_weight))
                    tree.column(col, width=width, stretch=True)
            except Exception:
                pass
        tree.bind("<Configure>", resize, add="+")
        tree.after(50, resize)


    def _make_toplevel_responsive(self, win, title=None, fullscreen=False):
        """Use the available monitor area instead of a hard-coded form size."""
        if title:
            win.title(title)
        win.update_idletasks()
        sw = win.winfo_screenwidth()
        sh = win.winfo_screenheight()
        if fullscreen:
            try:
                win.attributes("-fullscreen", True)
            except tk.TclError:
                win.geometry(f"{sw}x{sh}+0+0")
        else:
            w = max(900, int(sw * 0.94))
            h = max(600, int(sh * 0.88))
            x = max(0, (sw - w) // 2)
            y = max(0, (sh - h) // 2)
            win.geometry(f"{w}x{h}+{x}+{y}")
            win.minsize(min(w, 900), min(h, 600))
        win.bind("<Control-MouseWheel>", lambda e: "break", add="+")

