    def build_system_config_view(self, parent):
        """System Configuration: SLD + realtime variables only.

        The dark SLD follows the original plant System Configuration display.
        No data cards or panels are drawn over the equipment labels.
        """
        self._system_config_base_w = 1536.0
        self._system_config_base_h = 1024.0
        self.system_config_canvas = None
        self.system_config_variable_specs = []
        self.system_config_status_items = []
        self._system_config_source_image = None
        self._system_config_bg_photo = None
        self._system_config_image_b64 = ""

        frame = tk.Frame(parent, bg="#101010", bd=0, highlightthickness=0)
        frame.pack(fill="both", expand=True)

        header = tk.Frame(frame, bg="#101010", height=36, bd=0, highlightthickness=0)
        header.pack(fill="x", side="top")
        header.pack_propagate(False)
        tk.Label(header, text="SYSTEM CONFIGURATION", bg="#101010", fg="#ff9900",
                 font=("Arial", 13, "bold")).pack(side="left", padx=10)
        self.system_config_status_label = tk.Label(
            header, text="IEC-104 0/8  •  IP 0/8", bg="#101010", fg="#ff3333",
            font=("Arial", 10, "bold")
        )
        self.system_config_status_label.pack(side="right", padx=10)

        canvas = tk.Canvas(frame, bg="#101010", highlightthickness=0, bd=0, relief="flat")
        canvas.pack(fill="both", expand=True)
        self.system_config_canvas = canvas

        aux_stage_buttons = []
        for stage_no in (1, 2):
            button = tk.Button(
                canvas, text=f"AUX STG {stage_no}",
                bg="#ffd92f", fg="#4b3510", activebackground="#ffe76b",
                activeforeground="#4b3510", relief="raised", bd=2,
                font=("Times New Roman", 17, "bold"),
                command=lambda: self.switch_tab("aux_system")
            )
            aux_stage_buttons.append(button)

        try:
            clean_image_path = os.path.join(APP_DIR, "SYSTEMCONFIG_DARK.png")
            if os.path.exists(clean_image_path):
                self._system_config_source_image = Image.open(clean_image_path).convert("RGB")
            else:
                raw = base64.b64decode(self._system_config_image_b64)
                self._system_config_source_image = Image.open(__import__("io").BytesIO(raw)).convert("RGB")
        except Exception:
            self._system_config_source_image = None

        def add_variables(x, y, fields, source_ip=None, mode="STD", font_size=9, anchor="nw"):
            self.system_config_variable_specs.append({
                "x": float(x), "y": float(y), "fields": list(fields),
                "source": source_ip, "mode": mode, "font_size": int(font_size),
                "anchor": anchor, "items": []
            })

        wire_fields = [("UAB", "Uab"), ("IA", "Ia"), ("IB", "Ib"), ("IC", "Ic"), ("P", "P"), ("Q", "Q")]
        gen_fields = [("UAB", "Uab"), ("UBC", "Ubc"), ("UCA", "Uca"),
                      ("IA", "Ia"), ("IB", "Ib"), ("IC", "Ic"), ("P", "P"),
                      ("Q", "Q"), ("F", "f"), ("COS", "cos"), ("UE", "UE"), ("IE", "IE")]
        feeder_fields = [("UAB", "Uab"), ("IA", "Ia"), ("P", "P"), ("Q", "Q")]

        # Positions are relative to the 1536x1024 SLD, so they follow the diagram.
        # The reference page is intentionally kept clean: equipment names and
        # CT ratios are already part of the background image.

        def resize_system_config(_event=None):
            if self._system_config_source_image is None:
                return
            cw = max(100, canvas.winfo_width())
            ch = max(100, canvas.winfo_height())
            sx = cw / self._system_config_base_w
            sy = ch / self._system_config_base_h
            self._system_config_scale_x = sx
            self._system_config_scale_y = sy

            button_font = max(10, min(20, int(round(17 * min(sx, sy)))))
            button_y = max(8, int(round(20 * sy)))
            button_w = max(105, int(round(145 * sx)))
            button_h = max(42, int(round(58 * sy)))
            for index, button in enumerate(aux_stage_buttons):
                button.config(font=("Times New Roman", button_font, "bold"))
                button.place(
                    x=int(round((35 + index * 155) * sx)), y=button_y,
                    width=button_w, height=button_h
                )

            bg_w = max(1, int(round(self._system_config_base_w * sx)))
            bg_h = max(1, int(round(self._system_config_base_h * sy)))
            resized = self._system_config_source_image.resize((bg_w, bg_h), Image.Resampling.LANCZOS)
            self._system_config_bg_photo = ImageTk.PhotoImage(resized)
            canvas.delete("system_config_bg")
            canvas.create_image(0, 0, image=self._system_config_bg_photo, anchor="nw", tags="system_config_bg")
            canvas.tag_lower("system_config_bg")

            canvas.delete("system_config_variable")
            canvas.delete("system_config_status")
            self.system_config_status_items = []
            for spec_no, spec in enumerate(self.system_config_variable_specs):
                spec["items"] = []
                base_x = spec["x"] * sx
                base_y = spec["y"] * sy
                fs = max(6, min(12, int(round(spec["font_size"] * min(sx, sy)))))
                row_gap = fs + max(2, int(round(2 * sy)))
                for row, (label, key) in enumerate(spec["fields"]):
                    # Black card behind each System Configuration variable
                    # block gives the same SCADA card appearance as Run/Aux.
                    if row == 0:
                        card_h = row_gap * len(spec["fields"]) + 6
                        card_w = max(115 * sx, 95)
                        left = base_x - 4 if spec.get("anchor", "nw") == "nw" else base_x - card_w + 4
                        canvas.create_rectangle(left, base_y - 4, left + card_w, base_y + card_h,
                                                fill="#000000", outline="#159b36", width=1,
                                                tags="system_config_variable")
                    item = canvas.create_text(
                        base_x, base_y + row * row_gap, text=f"{label}: --",
                        anchor=spec.get("anchor", "nw"), fill="#00ff36",
                        font=("Arial Narrow", max(9, fs), "bold"), tags="system_config_variable"
                    )
                    spec["items"].append((item, label, key))
                    binding_key = f"system:panel{spec_no}:row{row}"
                    self._register_ui_binding("variables", binding_key, {
                        "page": "System Configuration", "element": label,
                        "mode": "default", "Device_Addr": spec.get("source", ""),
                        "Physical_Name": key
                    })
                    canvas.tag_bind(item, "<Double-Button-1>",
                                    lambda _event, bk=binding_key: self._open_binding_dialog(bk, "variables"))
            canvas.tag_raise("system_config_variable")

            # Cover every breaker body in the plant SLD, not only the fourteen
            # Run Monitor feeder breakers.
            assert len(SLD_BREAKER_SPECS) == 23
            for breaker_key, element, _bay, physical_names, bx, by in SLD_BREAKER_SPECS:
                item = canvas.create_rectangle(
                    (bx - 8.0) * sx, (by - 14.0) * sy,
                    (bx + 8.0) * sx, (by + 14.0) * sy,
                    fill="#808080", outline="#ffffff", width=1,
                    tags="system_config_status"
                )
                value_item = canvas.create_text(
                    bx * sx, by * sy, text="?", fill="#ffffff",
                    font=("Arial", max(8, int(round(12 * min(sx, sy)))), "bold"),
                    tags="system_config_status"
                )
                binding_key = f"system:breaker:{breaker_key}"
                self._register_ui_binding("statuses", binding_key, {
                    "page": "System Configuration", "element": element,
                    "mode": "default", "source_type": "status",
                    "field": physical_names[0],
                })
                canvas.tag_bind(item, "<Double-Button-1>",
                                lambda _event, bk=binding_key: self._open_binding_dialog(bk, "statuses"))
                self.system_config_status_items.append((item, binding_key, value_item))
            canvas.tag_raise("system_config_status")

        canvas.bind("<Configure>", resize_system_config, add="+")
        canvas.after(100, resize_system_config)
        self.update_system_config_cards()

    def update_system_config_cards(self):
        """Update live variable text only; no cards/panels are drawn."""
        if not hasattr(self, "system_config_variable_specs"):
            return
        canvas = getattr(self, "system_config_canvas", None)
        if canvas is None:
            return
        try:
            with DATA_LOCK:
                store = {ip: dict(values) for ip, values in DATA_STORE.items()}
                cards = {idx: dict(values) for idx, values in CARD_VALUE_STORE.items()}
                statuses = dict(VINCI_STATUS)
                hosts = dict(HOST_STATUS)

            for spec_no, spec in enumerate(self.system_config_variable_specs):
                mode = spec.get("mode")
                ip = spec.get("source")
                host_ok = bool(hosts.get(ip, False)) if ip else False
                iec_ok = bool(statuses.get(ip, False)) if ip else False

                if mode == "W1":
                    d = store.get("10.100.163.1", DEFAULT_DATA)
                    values = {"Uab": d.get("W1_Uab", 0.0), "Ia": d.get("W1_Ia", 0.0),
                              "Ib": d.get("W1_Ib", 0.0), "Ic": d.get("W1_Ic", 0.0),
                              "P": d.get("W1_P", 0.0), "Q": d.get("W1_Q", 0.0)}
                elif mode == "W2":
                    d = store.get("10.100.163.1", DEFAULT_DATA)
                    values = {"Uab": d.get("W2_Uab", 0.0), "Ia": d.get("W2_Ia", 0.0),
                              "Ib": d.get("W2_Ib", 0.0), "Ic": d.get("W2_Ic", 0.0),
                              "P": d.get("W2_P", 0.0), "Q": d.get("W2_Q", 0.0)}
                elif mode == "GEN":
                    values = store.get(ip, DEFAULT_DATA)
                elif mode and mode.startswith("P"):
                    pnum = int(mode[1:])
                    if 1 <= pnum <= 5:
                        source_ip = f"10.100.163.{pnum + 3}"
                        values = store.get(source_ip, DEFAULT_DATA)
                        host_ok = bool(hosts.get(source_ip, False))
                        iec_ok = bool(statuses.get(source_ip, False))
                    else:
                        values = DEFAULT_DATA
                        host_ok = iec_ok = False
                else:
                    values = store.get(ip, DEFAULT_DATA) if ip else DEFAULT_DATA

                color = "#008000" if iec_ok else ("#b8860b" if host_ok else "#cc0000")
                for row_no, (item, label, key) in enumerate(spec.get("items", [])):
                    value = values.get(key, 0.0)
                    override = self._resolve_ui_binding("variables", f"system:panel{spec_no}:row{row_no}")
                    if override is not None:
                        value = override
                    try:
                        display = f"{label}: {float(value):.3f}" if label == "COS" else f"{label}: {float(value):.2f}"
                    except Exception:
                        display = f"{label}: 0.00"
                    canvas.itemconfig(item, text=display, fill=color)

            self._update_sld_status_items(
                canvas,
                getattr(self, "system_config_status_items", []),
            )

            connected = sum(bool(statuses.get(f"10.100.163.{i}", False)) for i in range(1, 9))
            hosts_up = sum(bool(hosts.get(f"10.100.163.{i}", False)) for i in range(1, 9))
            if hasattr(self, "system_config_status_label"):
                status_color = "#008000" if connected == 8 else ("#b8860b" if hosts_up else "#cc0000")
                self.system_config_status_label.config(
                    text=f"IEC-104 {connected}/8  •  IP {hosts_up}/8", fg=status_color
                )
        except Exception:
            pass

    def check_ip_connection(self, ip_address, port=VINCI_PORT, timeout=0.5):
        """Check IEC 60870-5-104 TCP connection availability."""
        try:
            sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            sock.settimeout(timeout)
            result = sock.connect_ex((ip_address, port))
            sock.close()
            return result == 0
        except Exception:
            return False


    # ==============================================================================
    # >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
    # NETWORK - EDITABLE / BLOCKED SECTION
    # Semua kode NETWORK berada di antara marker ini.
    # Fokus edit: IP, GW, device cards, ukuran, posisi, warna, garis topology,
    # status online/offline, dan responsive layout NETWORK.
    # Jangan mengedit bagian di luar marker ini untuk perubahan tampilan NETWORK.
    # <<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<
    # ==============================================================================
    def check_host_reachable(self, ip_address, timeout_ms=700):
        """Check whether the IP host itself is reachable, independent of IEC104."""
        try:
            # Windows SCADA host: use one ICMP echo. -w is milliseconds.
            result = subprocess.run(
                ["ping", "-n", "1", "-w", str(timeout_ms), ip_address],
                stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL,
                creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0),
                timeout=(timeout_ms / 1000.0) + 0.5
            )
            return result.returncode == 0
        except Exception:
            return False

    def get_network_status(self, ip_address):
        """Return two independent real-time states: host alive and IEC104 connected."""
        with DATA_LOCK:
            host_alive = bool(HOST_STATUS.get(ip_address, False))
            iec_connected = bool(VINCI_STATUS.get(ip_address, False))
        return host_alive, iec_connected

    # ======================================================================
    # NETWORK ONLY - ISOLATED SUPERVISORY ENGINE
    # ======================================================================
    def host_status_worker(self):
        """Network-only IP reachability monitor.

        This worker updates HOST_STATUS only.  It does not modify any SCADA
        page, measurement value, alarm, generator state, or diagram state.
        """
        while True:
            monitored_ips = [rtu["ip"] for rtu in RTU_LIST]
            monitored_ips.extend(["10.100.163.101", "10.100.163.102"])
            # Ping concurrently so one unreachable address cannot make every
            # following card show an old status for several seconds.
            with ThreadPoolExecutor(max_workers=min(10, len(monitored_ips))) as pool:
                results = list(pool.map(
                    lambda address: self.check_host_reachable(address, timeout_ms=600),
                    monitored_ips
                ))
            for ip, alive in zip(monitored_ips, results):
                with DATA_LOCK:
                    HOST_STATUS[ip] = alive
            time.sleep(2.0)

    def get_network_status(self, ip_address):
        """Return host/IP reachability and IEC104 state independently."""
        with DATA_LOCK:
            return (
                bool(HOST_STATUS.get(ip_address, False)),
                bool(VINCI_STATUS.get(ip_address, False)),
            )

