MONITOR_TARGETS = {
    "G1": {"computer": "Computer D", "source": "MonitorTV.json/p1"},
    "G2": {"computer": "Computer E", "source": "MonitorTV.json/p2"},
}

try:
    # Portable JSON + standard-library HTTP mode. No Flask or Socket.IO.
    from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
    from urllib.parse import urlparse

    MONITOR_TV_AVAILABLE = True
    MONITOR_TV_PORT = 5000
    MONITOR_TV_JSON_PATH = os.path.join(APP_DIR, "MonitorTV.json")
    MONITOR_TV_HTML_PATH = os.path.join(APP_DIR, "MONITOR V55.html")
    MONITOR_TV_CONFIG_PATH = os.path.join(APP_DIR, "MonitorTVConfig.json")
    MONITOR_TV_CONFIG_LOCK = threading.RLock()
    MONITOR_TV_ACTIVE_ROLE = None
    MONITOR_TV_EDITOR_ROLES = frozenset({"Admin", "Developer"})

    def _monitor_tv_operator_allowed(remote_ip):
        """Allow counter controls only from configured SCADA and TV stations."""
        config = _communication_config()
        allowed_ips = {str(ip).strip() for ip in config.get("tv_editor_allowed_ips", [])}
        allowed_ips.update({_local_scada_ip(), "127.0.0.1", "::1"})
        return str(remote_ip) in allowed_ips

    def _monitor_tv_editor_allowed(remote_ip):
        """Authorize TV editing from the active privileged desktop session."""
        return (
            _monitor_tv_operator_allowed(remote_ip)
            and MONITOR_TV_ACTIVE_ROLE in MONITOR_TV_EDITOR_ROLES
        )
    def _default_operational_counter():
        """Keep a new day counter at zero until the operator presses Start."""
        return {
            "running": False,
            "started_at_epoch": None,
            "accumulated_seconds": 0.0,
        }

    def _normalize_operational_counter(value):
        """Return a safe, persistent counter state."""
        source = value if isinstance(value, dict) else {}
        running_value = source.get("running", False)
        if isinstance(running_value, str):
            running = running_value.strip().lower() in {"1", "true", "yes", "on"}
        else:
            running = bool(running_value)
        try:
            accumulated = float(source.get("accumulated_seconds", 0.0))
        except (TypeError, ValueError):
            accumulated = 0.0
        if not math.isfinite(accumulated) or accumulated < 0:
            accumulated = 0.0
        started_at = source.get("started_at_epoch")
        try:
            started_at = float(started_at) if started_at is not None else None
        except (TypeError, ValueError):
            started_at = None
        if started_at is not None and (not math.isfinite(started_at) or started_at < 0):
            started_at = None
        if running and started_at is None:
            started_at = time.time()
        return {
            "running": running,
            "started_at_epoch": started_at,
            "accumulated_seconds": accumulated,
        }

    def _operational_counter_snapshot(value):
        """Calculate completed operational days without mutating stored state."""
        state = _normalize_operational_counter(value)
        elapsed = state["accumulated_seconds"]
        if state["running"] and state["started_at_epoch"] is not None:
            elapsed += max(0.0, time.time() - state["started_at_epoch"])
        started_at = state["started_at_epoch"]
        return {
            "days": int(elapsed // 86400),
            "running": state["running"],
            "started_at": (
                datetime.datetime.fromtimestamp(started_at).isoformat(timespec="seconds")
                if started_at is not None else None
            ),
            "elapsed_seconds": int(elapsed),
        }


    def _monitor_tv_config():
        # Rectangle / junction dapat menggunakan nilai hasil telemetry mana pun.
        # ``operator`` dan ``threshold`` menentukan kondisi BENAR; warna serta
        # efek flow dapat diubah dari editor Monitor TV dan tersimpan di JSON.
        def rectangle(field, label, operator="=", threshold=1.0):
            return {
                "field": field,
                "label": label,
                "operator": operator,
                "threshold": threshold,
                "true_color": "#ff2020",
                "false_color": "#14d84a",
                "flow": "none",
            }

        default_rectangles = {
            "j-main": rectangle("ct3", "Main Junction"),
            "j-generator": rectangle("ll3", "Generator Junction"),
            "j-transformer": rectangle("rr1", "Transformer Junction"),
            "j-transformer-bottom": rectangle(
                "rr3", "Transformer Bottom", operator=">", threshold=0.0,
            ),
        }
        result = {
            "G1": {"variables": {}, "rectangles": {
                name: dict(item) for name, item in default_rectangles.items()}},
            "G2": {"variables": {}, "rectangles": {
                name: dict(item) for name, item in default_rectangles.items()}},
            "operational_counter": _default_operational_counter(),
        }
        config_changed = False
        try:
            with MONITOR_TV_CONFIG_LOCK, open(MONITOR_TV_CONFIG_PATH, "r", encoding="utf-8-sig") as handle:
                loaded = json.load(handle)
            if isinstance(loaded, dict):
                for monitor_id in ("G1", "G2"):
                    section = loaded.get(monitor_id, {})
                    if isinstance(section, dict):
                        result[monitor_id]["variables"].update(section.get("variables", {}))
                        result[monitor_id]["rectangles"].update(section.get("rectangles", {}))
                loaded_counter = loaded.get("operational_counter")
                if isinstance(loaded_counter, dict):
                    normalized_counter = _normalize_operational_counter(loaded_counter)
                    result["operational_counter"] = normalized_counter
                    if loaded_counter != normalized_counter:
                        config_changed = True
                else:
                    config_changed = True
        except Exception:
            pass
        # Seed new/incomplete TV bindings and refresh source metadata from the
        # authoritative ListSetting registry. The selected Bay/point remains
        # unchanged, while edits made in Parameter Setting propagate to TV.
        source_bays = {
            "auxiliary1": "1# Auxiliary Transformer",
            "auxiliary2": "2# Auxiliary Transformer",
            "measure_control1": "1# Measure Control Box",
            "measure_control2": "2# Measure Control Box",
            "wire1": "Connection Wire I",
            "wire2": "Connection Wire II",
            "voltage": "Voltage Monitoring",
        }
        maps = {
            "G1": globals().get("MONITOR_TV_FIELD_MAP_G1", {}),
            "G2": globals().get("MONITOR_TV_FIELD_MAP_G2", {}),
        }
        with SETTING_LOCK:
            registry = [dict(row) for row in SETTING_REGISTRY]
        for monitor_id, field_map in maps.items():
            variables = result[monitor_id]["variables"]
            for html_id, (source, key) in field_map.items():
                bay = source_bays.get(source, "")
                physical = str(key)
                if source == "wire1" and not physical.startswith("W1_"):
                    physical = "W1_" + physical
                elif source == "wire2" and not physical.startswith("W2_"):
                    physical = "W2_" + physical
                existing = variables.get(str(html_id), {})
                # Bay + Physical is the persistent selection identity. Default
                # bindings follow ListSetting changes; values explicitly saved
                # from the Monitor-TV editor remain authoritative.
                lookup_bay = str(existing.get("Bay_Name", bay)).strip() if isinstance(existing, dict) else bay
                lookup_physical = str(existing.get("Physical_Name", physical)).strip() if isinstance(existing, dict) else physical
                row = next((item for item in registry
                            if str(item.get("Bay_Name", "")).strip() == lookup_bay
                            and str(item.get("Physical_Name", "")).strip() == lookup_physical), None)
                if row is None and isinstance(existing, dict):
                    lookup_index = str(existing.get("Info_Index", "")).strip()
                    lookup_info = str(existing.get("Info_Name", "")).strip()
                    row = next((item for item in registry
                                if str(item.get("Bay_Name", "")).strip() == lookup_bay
                                and lookup_index
                                and str(item.get("Info_Index", "")).strip() == lookup_index), None)
                    if row is None:
                        row = next((item for item in registry
                                    if str(item.get("Bay_Name", "")).strip() == lookup_bay
                                    and lookup_info
                                    and str(item.get("Info_Name", "")).strip() == lookup_info), None)
                seeded = dict(existing) if isinstance(existing, dict) else {}
                seeded.setdefault("source", source)
                seeded.setdefault("key", str(key))
                seeded.setdefault("Decimals", 2)
                if row and seeded.get("mode") != "selected":
                    for column in SETTING_COLUMNS:
                        seeded[column] = row.get(column, "")
                if variables.get(str(html_id)) != seeded:
                    variables[str(html_id)] = seeded
                    config_changed = True
            # Older rectangle configurations only stored ``field``. Fill in
            # the linked variable address once for backwards compatibility,
            # while preserving any address edited directly on the rectangle.
            for rect_name, rectangle in result[monitor_id]["rectangles"].items():
                if not isinstance(rectangle, dict):
                    continue
                variable = variables.get(str(rectangle.get("field", "")), {})
                if not isinstance(variable, dict):
                    continue
                for column in SETTING_COLUMNS:
                    if column in variable and column not in rectangle:
                        rectangle[column] = variable.get(column)
                        config_changed = True
                if "source" not in rectangle:
                    rectangle["source"] = variable.get("source", "")
                    config_changed = True
                if "key" not in rectangle:
                    rectangle["key"] = variable.get("key", "")
                    config_changed = True

        # Refresh selected TV rectangles from StatusSetting while preserving
        # their display logic (label/colors/operator/threshold/flow).
        with STATUS_LOCK:
            status_rows = [dict(row) for row in STATUS_REGISTRY]
        for monitor_id in ("G1", "G2"):
            for _rect_name, rectangle in result[monitor_id]["rectangles"].items():
                if not isinstance(rectangle, dict) or rectangle.get("Source_Kind") != "rectangle_status_csv":
                    continue
                fixed_logic = {
                    "operator": "=", "threshold": 1.0,
                    "true_color": "#ff2020", "false_color": "#14d84a",
                    "on_color": "#ff2020", "off_color": "#14d84a",
                }
                for column, value in fixed_logic.items():
                    if rectangle.get(column) != value:
                        rectangle[column] = value
                        config_changed = True
                bay = str(rectangle.get("Bay_Name", "")).strip()
                info_name = str(rectangle.get("Info_Name", rectangle.get("InfoName", ""))).strip()
                info_index = str(rectangle.get("Info_Index", "")).strip()
                physical = str(rectangle.get("Physical_Name", "")).strip()
                candidates = [row for row in status_rows
                              if str(row.get("Bay_Name", "")).strip() == bay]
                row = next((item for item in candidates
                            if info_name and str(item.get("InfoName", "")).strip() == info_name), None)
                if row is None:
                    row = next((item for item in candidates
                                if info_index and str(item.get("Info_Index", "")).strip() == info_index), None)
                if row is None:
                    row = next((item for item in candidates
                                if physical and str(item.get("PhysicalName", "")).strip() == physical), None)
                if row is None:
                    continue
                refreshed = {
                    "Device_Addr": row.get("Device_Addr", ""),
                    "Bay_Name": row.get("Bay_Name", ""),
                    "Physical_Name": row.get("PhysicalName", ""),
                    "Info_Name": row.get("InfoName", ""),
                    "Info_Index": row.get("Info_Index", ""),
                    "Jian_Ge_Id": row.get("Jian_Ge_Id", ""),
                    "ASDU": row.get("Parsed_ASDU", ""),
                    "IOA": row.get("Parsed_IOA", ""),
                    "Reverse": row.get("Reverse", ""),
                    "SetStr": row.get("SetStr", ""),
                    "ResetStr": row.get("ResetStr", ""),
                    "Source_Kind": "rectangle_status_csv",
                }
                for column, value in refreshed.items():
                    if rectangle.get(column) != value:
                        rectangle[column] = value
                        config_changed = True

        # Convert legacy analog-driven TV rectangles to digital StatusSetting
        # points. Once an operator selects another status row, Source_Kind is
        # already rectangle_status_csv and that explicit choice is preserved.
        status_targets = {
            "G1": {
                "j-main": ("Connection Wire I", ("breaker position",)),
                "j-generator": ("1# Measure Control Box", ("1# G circuit breaker close position",)),
                "j-transformer": ("1# Auxiliary Transformer", ("hv breaker close",)),
                "j-transformer-bottom": ("1# Auxiliary Transformer", ("UV breaker close",)),
            },
            "G2": {
                "j-main": ("Connection Wire II", ("breaker position",)),
                "j-generator": ("2# Measure Control Box", ("2# G circuit breaker close position",)),
                "j-transformer": ("2# Auxiliary Transformer", ("hv breaker close",)),
                "j-transformer-bottom": ("2# Auxiliary Transformer", ("UV breaker close",)),
            },
        }
        analog_only_columns = ("Coefficient", "CTPT", "Formula", "Add_Offset",
                               "Unit", "Decimals", "Type", "Min_Save_Mode",
                               "Tolerance", "Alarm_Class", "UUp_Limit", "Up_Limit",
                               "Down_Limit", "DDown_Limit")
        for monitor_id, targets in status_targets.items():
            rectangles = result[monitor_id]["rectangles"]
            for rectangle_id, (bay_name, preferred_names) in targets.items():
                rectangle = rectangles.get(rectangle_id)
                if not isinstance(rectangle, dict):
                    continue
                if rectangle.get("Source_Kind") == "rectangle_status_csv":
                    continue
                status_binding = _status_binding_for_bay(bay_name, preferred_names)
                if not status_binding:
                    continue
                rectangle.update(status_binding)
                rectangle["operator"] = "="
                rectangle["threshold"] = 1.0
                rectangle["true_color"] = "#ff2020"
                rectangle["false_color"] = "#14d84a"
                rectangle["on_color"] = "#ff2020"
                rectangle["off_color"] = "#14d84a"
                for column in analog_only_columns:
                    rectangle.pop(column, None)
                config_changed = True
        # Do not persist normalization from this read path.  Monitor-TV is
        # served by more than one SCADA process, so saving a result assembled
        # from a stale snapshot can overwrite a CT/PT edit that was just
        # submitted by the operator.  Explicit POST requests remain the only
        # writer for MonitorTVConfig.json; the normalized result is still used
        # in memory for the current response.
        return result

    def _save_monitor_tv_config(config):
        temporary = MONITOR_TV_CONFIG_PATH + ".tmp"
        with MONITOR_TV_CONFIG_LOCK:
            with open(temporary, "w", encoding="utf-8") as handle:
                json.dump(config, handle, ensure_ascii=False, indent=2)
            os.replace(temporary, MONITOR_TV_CONFIG_PATH)

    def _monitor_tv_preview(binding):
        """Calculate an unsaved Monitor-TV binding from its exact live IEC point."""
        if not isinstance(binding, dict):
            raise ValueError("Data preview tidak valid")
        ip = str(binding.get("Device_Addr", "")).strip()
        if not ip:
            raise ValueError("Device IP wajib diisi")
        try:
            asdu = int(float(binding.get("ASDU")))
            ioa = int(float(binding.get("IOA")))
        except (TypeError, ValueError, OverflowError):
            raise ValueError("ASDU dan IOA wajib berupa angka") from None

        bay = str(binding.get("Bay_Name", "")).strip()
        formula = _norm_formula(binding.get("Formula"))
        derived = formula in {"DERIVED_P", "DERIVED_Q", "DERIVED_I"}
        address_key = (ip, asdu, ioa)
        with DATA_LOCK:
            raw_value = (
                0.0 if derived else RAW_ADDRESS_STORE.get(address_key)
            )
            captured_at = RAW_ADDRESS_TIMESTAMP.get(address_key)
            online = bool(VINCI_STATUS.get(ip, False))
            source_values = dict(BAY_VALUE_STORE.get(bay, {}))

        unit = str(binding.get("Unit", "")).strip()
        try:
            decimals = int(float(binding.get("Decimals", 2)))
        except (TypeError, ValueError, OverflowError):
            decimals = 2
        decimals = max(0, min(6, decimals))
        formula_text = FORMULA_PRESETS.get(
            formula,
            str(binding.get("Formula", "")).strip() or "Raw",
        )
        result = {
            "ok": True,
            "online": online,
            "available": raw_value is not None,
            "device_ip": ip,
            "asdu": asdu,
            "ioa": ioa,
            "raw": raw_value,
            "actual": None,
            "formatted": "—",
            "unit": unit,
            "decimals": decimals,
            "formula": formula_text,
            "age_seconds": (
                max(0.0, time.monotonic() - captured_at)
                if captured_at is not None
                else None
            ),
        }
        if raw_value is None:
            result["message"] = (
                f"Belum ada data RAW untuk {ip} / ASDU {asdu} / IOA {ioa}."
            )
            return result

        calculated = _calculate_formula(
            float(raw_value),
            binding,
            source_values,
        )
        if not math.isfinite(float(calculated)):
            raise ValueError("Hasil formula tidak valid")
        result["actual"] = float(calculated)
        result["formatted"] = f"{float(calculated):.{decimals}f}"
        result["message"] = (
            "Preview live sesuai data RTU saat ini."
            if online
            else "RTU offline; preview memakai data RAW terakhir yang diterima."
        )
        return result
    def _set_operational_counter(action, started_at=None):
        """Persist a reset, an immediate start, or an operator-selected start."""
        action = str(action or "").strip().lower()
        if action == "start":
            action = "start_now"
        if action not in {"reset", "start_now", "set_start"}:
            raise ValueError("Aksi operational days tidak valid")

        selected_epoch = None
        if action == "set_start":
            selected_text = str(started_at or "").strip()
            if not selected_text:
                raise ValueError("Tanggal dan jam mulai wajib diisi")
            try:
                selected_epoch = datetime.datetime.fromisoformat(selected_text).timestamp()
            except (TypeError, ValueError, OverflowError):
                raise ValueError("Tanggal atau jam mulai tidak valid") from None
            if not math.isfinite(selected_epoch) or selected_epoch < 0:
                raise ValueError("Tanggal atau jam mulai tidak valid")

        with MONITOR_TV_CONFIG_LOCK:
            config = _monitor_tv_config()
            if action == "reset":
                state = _default_operational_counter()
            else:
                state = {
                    "running": True,
                    "started_at_epoch": (
                        time.time() if action == "start_now" else selected_epoch
                    ),
                    "accumulated_seconds": 0.0,
                }
            config["operational_counter"] = state
            _save_monitor_tv_config(config)
        return _operational_counter_snapshot(state)



    # ========================================================================
    # MONITOR TV - FIELD MAPPING
    # ========================================================================
    # EDIT BAGIAN INI SAJA jika ingin mengganti sumber data HTML.
    # source = auxiliary      -> BAY_VALUE_STORE Auxiliary Transformer G1/G2
    # source = voltage        -> DATA_STORE Voltage Transformer Monitoring Device
    # source = wire           -> DATA_STORE RTU Connection Wire (W1/W2)
    # source = measure_control -> BAY_VALUE_STORE Measure Control Box G1/G2
    # key    = nama field DATA_STORE yang akan dibaca.
    #
    # CATATAN: tk4 sengaja Uca sesuai mapping yang diberikan.
    MONITOR_TV_FIELD_MAP_G1 = {
        # HTML ID : (source, DATA_STORE key)
        "tk1": ("auxiliary1", "Uab"),
        "tk2": ("voltage", "Uab"),
        "tk3": ("voltage", "Ubc"),
        "tk4": ("voltage", "Uca"),

        "ct1": ("wire1", "Uab"),
        "ct2": ("wire1", "f"),
        "ct3": ("wire1", "Ia"),
        "ct4": ("wire1", "P"),
        "ct5": ("wire1", "Q"),

        "ll1": ("measure_control1", "P"),
        "ll2": ("measure_control1", "Q"),
        "ll3": ("measure_control1", "IE"),
        "ll4": ("measure_control1", "UE"),
        "ll5": ("measure_control1", "cos"),

        "cm1": ("measure_control1", "Uab"),
        "cm2": ("measure_control1", "f"),
        "cm3": ("measure_control1", "Ia"),
        "cm4": ("measure_control1", "Ib"),
        "cm5": ("measure_control1", "Ic"),

        "rr1": ("auxiliary1", "Ia"),
        "rr2": ("auxiliary1", "P"),
        "rr3": ("measure_control1", "Uab_L"),
    }

    MONITOR_TV_FIELD_MAP_G2 = {
        html_id: (
            source.replace("wire1", "wire2")
                  .replace("auxiliary1", "auxiliary2")
                  .replace("measure_control1", "measure_control2"),
            (
                data_key
            ),
        )
        for html_id, (source, data_key) in MONITOR_TV_FIELD_MAP_G1.items()
    }
    # G2 top phase-voltage estimates use its own Wire II line voltages.
    # The saved MonitorTVConfig formula converts each line value by sqrt(3).
    MONITOR_TV_FIELD_MAP_G2.update({
        "tk2": ("wire2", "Uab_phase"),
        "tk3": ("wire2", "Ubc_phase"),
        "tk4": ("wire2", "Uca_phase"),
    })

    def _monitor_tv_generator_payload(source_ip, wire_prefix=None, display_name=None):
        """Build one Monitor-TV payload using MONITOR_TV_FIELD_MAP."""
        field_map = (
            MONITOR_TV_FIELD_MAP_G2
            if str(wire_prefix or "").strip().upper() == "W2"
            else MONITOR_TV_FIELD_MAP_G1
        )
        monitor_id = "G2" if str(wire_prefix or "").strip().upper() == "W2" else "G1"
        config = _monitor_tv_config().get(monitor_id, {})
        field_map = dict(field_map)
        configured_variables = config.get("variables", {})
        for html_id, item in configured_variables.items():
            if isinstance(item, dict) and item.get("source") and item.get("key"):
                field_map[str(html_id)] = (str(item["source"]), str(item["key"]))
        with DATA_LOCK:
            generator_values = dict(
                DATA_STORE.get(source_ip, DEFAULT_DATA)
            )
            generator_online = bool(
                VINCI_STATUS.get(source_ip, False)
            )

            wire_ip = "10.100.163.1"
            wire_values = dict(
                DATA_STORE.get(wire_ip, DEFAULT_DATA)
            )
            wire_online = bool(
                VINCI_STATUS.get(wire_ip, False)
            )

            voltage_monitor_ip = "10.100.163.7"
            voltage_values = dict(
                DATA_STORE.get(
                    voltage_monitor_ip,
                    DEFAULT_DATA
            )
        )

            aux_transformer_values = dict(
                BAY_VALUE_STORE.get(
                    "2# Auxiliary Transformer" if wire_prefix == "W2" else "1# Auxiliary Transformer",
                    {}
            )
        )

            measure_control_values = dict(
                BAY_VALUE_STORE.get(
                    "2# Measure Control Box" if wire_prefix == "W2" else "1# Measure Control Box",
                    {}
                )
            )
            raw_bay_values = {bay: dict(values) for bay, values in RAW_BAY_VALUE_STORE.items()}
            raw_ip_values = {ip: dict(values) for ip, values in RAW_STORE.items()}
            engineered_bay_values = {bay: dict(values) for bay, values in BAY_VALUE_STORE.items()}

        now = time.localtime()
        prefix = str(wire_prefix or "").strip()

        def read_value(values, key, default=0.0):
            try:
                value = float(values.get(key, default) or default)
                return value if math.isfinite(value) else float(default)
            except (TypeError, ValueError):
                return float(default)

        def read_source(source, key):
            if source == "generator":
                return read_value(generator_values, key)

            if source in {"wire1", "wire2"}:
                source_prefix = "W2" if source == "wire2" else "W1"
                wire_key = f"{source_prefix}_{key}"
                return read_value(wire_values, wire_key)

            if source == "voltage":
                return read_value(voltage_values, key)

            if source in {"auxiliary1", "auxiliary2"}:
                return read_value(aux_transformer_values, key)

            if source in {"measure_control1", "measure_control2"}:
                return read_value(measure_control_values, key)

            return 0.0

        payload = {
            "source": display_name or source_ip,
            "date": time.strftime("%Y-%m-%d", now),
            "time": time.strftime("%H:%M:%S", now),
        }

        for html_id, (source, data_key) in field_map.items():
            payload[html_id] = read_source(source, data_key)
        # Apply the Monitor-TV binding to the RAW point. This makes Coefficient,
        # CT/PT, Formula, and Add Offset saved in the editor affect the display
        # instead of reusing the ListSetting-engineered value unchanged.
        for html_id, item in configured_variables.items():
            if not isinstance(item, dict):
                continue
            bay = str(item.get("Bay_Name", "")).strip()
            physical = str(item.get("Physical_Name", "")).strip()
            if not bay or not physical:
                continue
            raw_physical = _runtime_physical_name(item) or physical
            formula = _norm_formula(item.get("Formula"))
            raw_value = None
            if formula in {"DERIVED_P", "DERIVED_Q", "DERIVED_I"}:
                raw_value = 0.0
            else:
                raw_value = raw_bay_values.get(bay, {}).get(raw_physical)
                if raw_value is None:
                    ip = str(item.get("Device_Addr", "")).strip()
                    raw_value = raw_ip_values.get(ip, {}).get(raw_physical)
                if raw_value is None and raw_physical != physical:
                    raw_value = raw_bay_values.get(bay, {}).get(physical)
                if raw_value is None:
                    ip = str(item.get("Device_Addr", "")).strip()
                    raw_value = raw_ip_values.get(ip, {}).get(physical)
            if raw_value is None:
                continue
            try:
                calculated = _calculate_formula(
                    float(raw_value), item, engineered_bay_values.get(bay, {}),
                )
                if math.isfinite(float(calculated)):
                    payload[str(html_id)] = float(calculated)
            except Exception:
                continue
        # Hindari menampilkan angka cache dari RTU yang sedang offline.
        for html_id, (source, data_key) in field_map.items():
            if source.startswith("measure_control") and not generator_online:
                payload[html_id] = 0.0
            elif (source.startswith("wire") or source.startswith("auxiliary")) and not wire_online:
                payload[html_id] = 0.0

        payload["online"] = generator_online
        payload["wire_online"] = wire_online
        # Rectangle selalu membaca nilai IEC-104 RAW.  Formula/koefisien pada
        # card layar tidak ikut diterapkan terhadap logika warna rectangle.
        rectangle_values = {}
        for rectangle_id, item in config.get("rectangles", {}).items():
            if not isinstance(item, dict):
                continue
            linked = configured_variables.get(str(item.get("field", "")), {})
            binding = dict(linked) if isinstance(linked, dict) else {}
            binding.update(item)
            bay = str(binding.get("Bay_Name", "")).strip()
            physical = str(binding.get("Physical_Name", "")).strip()
            ip = str(binding.get("Device_Addr", "")).strip()
            if binding.get("Source_Kind") == "rectangle_status_csv":
                info_name = str(binding.get("Info_Name", binding.get("InfoName", ""))).strip()
                info_index = str(binding.get("Info_Index", "")).strip()
                status_value = None
                with DATA_LOCK:
                    if ip and bool(VINCI_STATUS.get(ip, False)):
                        if info_name:
                            status_value = STATUS_VALUE_STORE.get((ip, "info", info_name))
                        if status_value is None and physical:
                            status_value = STATUS_VALUE_STORE.get((ip, "physical", physical))
                        if status_value is None and info_index:
                            status_value = STATUS_VALUE_STORE.get((ip, "index", info_index))
                # Null explicitly means that neither open nor closed is known.
                rectangle_values[str(rectangle_id)] = (
                    None if status_value is None else int(status_value)
                )
            elif bay and physical:
                rectangle_values[str(rectangle_id)] = read_value(raw_bay_values.get(bay, {}), physical)
            elif ip and physical:
                rectangle_values[str(rectangle_id)] = read_value(raw_ip_values.get(ip, {}), physical)
        payload["rectangles"] = config.get("rectangles", {})
        payload["rectangle_values"] = rectangle_values
        return payload

    def _monitor_tv_payload():
        # HYBRID ROUTING — the screen layout is untouched.
        # G1/G2 normal blocks stay on their generator RTUs.
        # ONLY the central red-marked block uses RTU1 Connection Wire:
        #   G1 -> W1_* / Connection Wire I
        #   G2 -> W2_* / Connection Wire II
        try:
            g1_ip = getattr(scada_app_instance, "GEN_1_IP", RTU_LIST[1]["ip"])
            g2_ip = getattr(scada_app_instance, "GEN_2_IP", RTU_LIST[2]["ip"])
        except Exception:
            g1_ip = RTU_LIST[1]["ip"]
            g2_ip = RTU_LIST[2]["ip"]

        result = {
            "p1": _monitor_tv_generator_payload(
                g1_ip, "W1", "G1 / GENERATOR 1 + CONNECTION WIRE I"
            ),
            "p2": _monitor_tv_generator_payload(
                g2_ip, "W2", "G2 / GENERATOR 2 + CONNECTION WIRE II"
            ),
            "mapping": MONITOR_TARGETS,
        }
        operational = _operational_counter_snapshot(
            _monitor_tv_config().get("operational_counter")
        )
        for panel in (result["p1"], result["p2"]):
            panel["operational_days"] = operational["days"]
            panel["operational_counter"] = operational
        return result


    def _breaker_status_row(identifier, display_name, binding, used_in, binding_keys):
        """Resolve one configured breaker without creating a second IEC-104 client."""
        ip = str(binding.get("Device_Addr", "")).strip()
        bay = str(binding.get("Bay_Name", "")).strip()
        physical = str(binding.get("Physical_Name", "")).strip()
        info_name = str(binding.get("Info_Name", binding.get("InfoName", ""))).strip()
        info_index = str(binding.get("Info_Index", "")).strip()
        reverse_raw = binding.get("Reverse", 0)
        reverse_enabled = str(reverse_raw or "").strip().lower() in {
            "-1", "1", "true", "yes", "on",
        }
        raw_value = None
        with DATA_LOCK:
            rtu_online = bool(ip and VINCI_STATUS.get(ip, False))
            if rtu_online:
                if info_name:
                    raw_value = STATUS_VALUE_STORE.get((ip, "info", info_name))
                if raw_value is None and physical:
                    raw_value = STATUS_VALUE_STORE.get((ip, "physical", physical))
                if raw_value is None and info_index:
                    raw_value = STATUS_VALUE_STORE.get((ip, "index", info_index))

        if not ip:
            quality = "CONFIG INVALID"
        elif not rtu_online:
            quality = "RTU OFFLINE"
        elif raw_value is None:
            quality = "POINT NOT RECEIVED"
        else:
            quality = "GOOD"

        if raw_value is None:
            raw_yx = None
            effective_yx = None
            condition = "Unknown"
            color_name = "Abu-abu"
            color_hex = "#808080"
        else:
            raw_yx = int(float(raw_value))
            effective_yx = _cbz_breaker_state(raw_yx, reverse_raw)
            if effective_yx == 1:
                condition = "Closed/On"
                color_name = "Merah"
                color_hex = "#ff2020"
            else:
                condition = "Open/Off"
                color_name = "Hijau"
                color_hex = "#14d84a"

        return {
            "id": str(identifier),
            "display_name": str(display_name or bay or identifier),
            "used_in": sorted({str(item) for item in used_in if str(item).strip()}),
            "binding_keys": sorted({str(item) for item in binding_keys}),
            "device_addr": ip,
            "bay_name": bay,
            "physical_name": physical,
            "info_name": info_name,
            "info_index": info_index,
            "asdu": binding.get("ASDU", ""),
            "ioa": binding.get("IOA", ""),
            "set_str": binding.get("SetStr", ""),
            "reset_str": binding.get("ResetStr", ""),
            "source_kind": binding.get("Source_Kind", ""),
            "source": f"IEC-104 {ip} · {bay} · {info_name or physical}",
            "raw_yx": raw_yx,
            "reverse": 1 if reverse_enabled else 0,
            "effective_yx": effective_yx,
            "condition": condition,
            "color_name": color_name,
            "color_hex": color_hex,
            "quality": quality,
            "rtu_online": rtu_online,
            "expected_rule": "Effective YX = Raw YX XOR Reverse",
        }

    def _breaker_status_payload():
        """Describe every unique SCADA breaker and every Monitor-TV rectangle."""
        app = globals().get("scada_app_instance")
        ui_bindings = getattr(app, "ui_bindings", {}) if app is not None else {}
        statuses = ui_bindings.get("statuses", {}) if isinstance(ui_bindings, dict) else {}
        grouped = {}
        for binding_key, item in statuses.items():
            if not isinstance(item, dict) or item.get("Source_Kind") != "rectangle_status_csv":
                continue
            signature = (
                str(item.get("Device_Addr", "")).strip(),
                str(item.get("Bay_Name", "")).strip(),
                str(item.get("Info_Name", item.get("InfoName", ""))).strip(),
                str(item.get("Info_Index", "")).strip(),
                str(item.get("ASDU", "")).strip(),
                str(item.get("IOA", "")).strip(),
                str(item.get("Reverse", "0")).strip(),
            )
            group = grouped.setdefault(signature, {
                "binding": dict(item), "used_in": set(), "binding_keys": [],
            })
            group["used_in"].add(item.get("page", str(binding_key).split(":", 1)[0]))
            group["binding_keys"].append(binding_key)

        breakers = []
        for index, (_signature, group) in enumerate(
                sorted(grouped.items(), key=lambda pair: (
                    str(pair[1]["binding"].get("Bay_Name", "")),
                    str(pair[1]["binding"].get("Device_Addr", "")),
                    str(pair[1]["binding"].get("IOA", "")),
                )), 1):
            binding = group["binding"]
            breakers.append(_breaker_status_row(
                f"breaker-{index}",
                binding.get("Bay_Name", binding.get("element", f"Breaker {index}")),
                binding,
                group["used_in"],
                group["binding_keys"],
            ))

        monitor_tv = []
        tv_config = _monitor_tv_config()
        for monitor_id in ("G1", "G2"):
            rectangles = tv_config.get(monitor_id, {}).get("rectangles", {})
            for rectangle_id, binding in sorted(rectangles.items()):
                if not isinstance(binding, dict) or binding.get("Source_Kind") != "rectangle_status_csv":
                    continue
                monitor_tv.append(_breaker_status_row(
                    f"{monitor_id}:{rectangle_id}",
                    f"{monitor_id} · {binding.get('label', rectangle_id)}",
                    binding,
                    [f"Monitor TV {monitor_id}"],
                    [f"{monitor_id}:{rectangle_id}"],
                ))

        return {
            "schema": "SCADA-BONT-BREAKER-STATUS-1",
            "generated_at": datetime.datetime.now().isoformat(timespec="milliseconds"),
            "rule": "Effective YX = Raw YX XOR Reverse",
            "legend": {
                "0": {"condition": "Open/Off", "color_name": "Hijau", "color_hex": "#14d84a"},
                "1": {"condition": "Closed/On", "color_name": "Merah", "color_hex": "#ff2020"},
                "unknown": {"condition": "Unknown", "color_name": "Abu-abu", "color_hex": "#808080"},
            },
            "matrix": [
                {"raw_yx": 0, "reverse": 0, "effective_yx": 0, "condition": "Open/Off", "color_name": "Hijau"},
                {"raw_yx": 1, "reverse": 0, "effective_yx": 1, "condition": "Closed/On", "color_name": "Merah"},
                {"raw_yx": 0, "reverse": 1, "effective_yx": 1, "condition": "Closed/On", "color_name": "Merah"},
                {"raw_yx": 1, "reverse": 1, "effective_yx": 0, "condition": "Open/Off", "color_name": "Hijau"},
            ],
            "breakers": breakers,
            "monitor_tv": monitor_tv,
        }


    def _full_realtime_relay_payload():
        """Complete read-only snapshot consumed by the second SCADA PC."""
        # The slave receives engineered telemetry, not RAW IEC values.
        # Include the configured G2 phase estimates as separate wire keys.
        g2_phase_values = _monitor_tv_generator_payload(RTU_LIST[2]["ip"], "W2")
        with DATA_LOCK:
            data_store = {ip: dict(values) for ip, values in DATA_STORE.items()}
            wire_values = data_store.setdefault("10.100.163.1", {})
            for field, key in (("tk2", "W2_Uab_phase"),
                               ("tk3", "W2_Ubc_phase"),
                               ("tk4", "W2_Uca_phase")):
                value = g2_phase_values.get(field)
                if isinstance(value, (int, float)) and math.isfinite(value):
                    wire_values[key] = float(value)
            return {
                "schema": "SCADA-BONT-RELAY-1",
                "generated_at": datetime.datetime.now().isoformat(timespec="milliseconds"),
                "source_ip": _communication_config().get("master_ip", "10.100.163.149"),
                "data_store": data_store,
                "bay_store": {bay: dict(values) for bay, values in BAY_VALUE_STORE.items()},
                "card_store": {str(idx): dict(values) for idx, values in CARD_VALUE_STORE.items()},
                "vinci_status": dict(VINCI_STATUS),
                "status_store": [
                    {"ip": key[0], "kind": key[1], "key": key[2], "value": value}
                    for key, value in STATUS_VALUE_STORE.items()
                    if isinstance(key, tuple) and len(key) == 3
                ],
            }

    def _monitor_tv_json_writer():
        while True:
            try:
                temporary = MONITOR_TV_JSON_PATH + ".tmp"
                with open(temporary, "w", encoding="utf-8") as json_file:
                    json.dump(_monitor_tv_payload(), json_file, ensure_ascii=False, indent=2)
                os.replace(temporary, MONITOR_TV_JSON_PATH)
            except Exception as exc:
                print(f"Monitor TV JSON write error: {exc}")
            time.sleep(1.0)

    class MonitorTVRequestHandler(BaseHTTPRequestHandler):
        """Serve G1/G2 HTML and the atomic JSON snapshot locally."""
        def do_GET(self):
            path = urlparse(self.path).path.rstrip("/") or "/G1"
            if path in ("/G1", "/G2", "/"):
                try:
                    with open(MONITOR_TV_HTML_PATH, "r", encoding="utf-8") as html_file:
                        html = html_file.read().replace("LOGO_PLACEHOLDER", BONT_LOGO_BASE64)
                    body = html.encode("utf-8")
                    self.send_response(200)
                    self.send_header("Content-Type", "text/html; charset=utf-8")
                    self.send_header("Cache-Control", "no-store, no-cache, must-revalidate, max-age=0")
                    self.send_header("Pragma", "no-cache")
                    self.send_header("Expires", "0")
                except Exception as exc:
                    body = f"Monitor TV HTML tidak tersedia: {exc}".encode("utf-8")
                    self.send_response(500)
                    self.send_header("Content-Type", "text/plain; charset=utf-8")
            elif path == "/MonitorTV.json":
                try:
                    with open(MONITOR_TV_JSON_PATH, "rb") as json_file:
                        body = json_file.read()
                    self.send_response(200)
                    self.send_header("Content-Type", "application/json; charset=utf-8")
                    self.send_header("Cache-Control", "no-store, no-cache, must-revalidate")
                except Exception as exc:
                    body = json.dumps({"error": str(exc)}).encode("utf-8")
                    self.send_response(503)
                    self.send_header("Content-Type", "application/json; charset=utf-8")
            elif path == "/BreakerStatus.json":
                body = json.dumps(
                    _breaker_status_payload(), ensure_ascii=False, indent=2,
                ).encode("utf-8")
                self.send_response(200)
                self.send_header("Content-Type", "application/json; charset=utf-8")
                self.send_header("Cache-Control", "no-store")
            elif path == "/MonitorTVConfig.json":
                body = json.dumps(_monitor_tv_config(), ensure_ascii=False).encode("utf-8")
                self.send_response(200)
                self.send_header("Content-Type", "application/json; charset=utf-8")
                self.send_header("Cache-Control", "no-store")
            elif path == "/MonitorTVOptions.json":
                remote_ip = str(self.client_address[0])
                if not _monitor_tv_editor_allowed(remote_ip):
                    body = json.dumps({
                        "ok": False,
                        "message": (
                            "Login aplikasi desktop sebagai Admin atau Developer "
                            "untuk membuka editor Monitor TV."
                        ),
                    }, ensure_ascii=False).encode("utf-8")
                    self.send_response(403)
                    self.send_header("Content-Type", "application/json; charset=utf-8")
                else:
                    with SETTING_LOCK:
                        options = [{key: row.get(key, "") for key in SETTING_COLUMNS} for row in SETTING_REGISTRY]
                    # Numeric TV fields use ListSetting. Rectangle choices use
                    # the isolated StatusSetting registry for every configured bay.
                    for row in _load_status_settings():
                        options.append({
                            "Device_Addr": row.get("Device_Addr", ""),
                            "Bay_Name": row.get("Bay_Name", ""),
                            "Physical_Name": row.get("PhysicalName", ""),
                            "Info_Name": row.get("InfoName", ""),
                            "Info_Index": row.get("Info_Index", ""),
                            "ASDU": row.get("Parsed_ASDU", ""),
                            "IOA": row.get("Parsed_IOA", ""),
                            "Coefficient": 1,
                            "CTPT": 1,
                            "Formula": "RAW",
                            "Add_Offset": 0,
                            "Unit": "",
                            "Decimals": 0,
                            "Source_Kind": "rectangle_status_csv",
                            "SetStr": row.get("SetStr", ""),
                            "ResetStr": row.get("ResetStr", ""),
                            "Reverse": row.get("Reverse", ""),
                        })
                    body = json.dumps(options, ensure_ascii=False).encode("utf-8")
                    self.send_response(200)
                    self.send_header("Content-Type", "application/json; charset=utf-8")
                    self.send_header("Cache-Control", "no-store")
            else:
                body = b"Not Found"
                self.send_response(404)
                self.send_header("Content-Type", "text/plain; charset=utf-8")
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)

        def do_POST(self):
            path = urlparse(self.path).path.rstrip("/")
            remote_ip = str(self.client_address[0])
            allowed_paths = {
                "/MonitorTVConfig.json",
                "/MonitorTVPreview.json",
                "/OperationalDays.json",
            }
            requires_privileged_role = path in {
                "/MonitorTVConfig.json",
                "/MonitorTVPreview.json",
            }
            can_write = (
                _monitor_tv_editor_allowed(remote_ip)
                if requires_privileged_role
                else _monitor_tv_operator_allowed(remote_ip)
            )
            if path not in allowed_paths or not can_write:
                body = json.dumps({
                    "ok": False,
                    "message": (
                        "Login aplikasi desktop sebagai Admin atau Developer "
                        "untuk mengubah konfigurasi Monitor TV."
                        if requires_privileged_role
                        else "Akses ditolak."
                    ),
                }, ensure_ascii=False).encode("utf-8")
                self.send_response(403)
                self.send_header("Content-Type", "application/json; charset=utf-8")
                self.send_header("Content-Length", str(len(body)))
                self.end_headers()
                self.wfile.write(body)
                return
            try:
                max_length = (
                    4096
                    if path in {"/OperationalDays.json", "/MonitorTVPreview.json"}
                    else 262144
                )
                length = min(
                    int(self.headers.get("Content-Length", "0")),
                    max_length,
                )
                request_body = json.loads(
                    self.rfile.read(length).decode("utf-8")
                )
                if path == "/MonitorTVPreview.json":
                    response = _monitor_tv_preview(request_body)
                elif path == "/OperationalDays.json":
                    if not isinstance(request_body, dict):
                        raise ValueError(
                            "Permintaan operational days tidak valid"
                        )
                    action = str(
                        request_body.get("action", "")
                    ).strip().lower()
                    state = _set_operational_counter(
                        action,
                        request_body.get("started_at"),
                    )
                    messages = {
                        "reset": "Operational days direset ke 0",
                        "start": "Penghitung dimulai dari waktu saat ini",
                        "start_now": (
                            "Penghitung dimulai dari waktu saat ini"
                        ),
                        "set_start": "Tanggal dan jam mulai disimpan",
                    }
                    response = {
                        "ok": True,
                        "message": messages.get(
                            action,
                            "Pengaturan tersimpan",
                        ),
                        "state": state,
                    }
                else:
                    config = request_body
                    if (
                        not isinstance(config, dict)
                        or not all(key in config for key in ("G1", "G2"))
                    ):
                        raise ValueError("Konfigurasi TV tidak valid")
                    _save_monitor_tv_config(config)
                    response = {"ok": True, "message": "Save berhasil"}
                body = json.dumps(
                    response,
                    ensure_ascii=False,
                ).encode("utf-8")
                self.send_response(200)
                self.send_header(
                    "Content-Type",
                    "application/json; charset=utf-8",
                )
            except Exception as exc:
                body = json.dumps({
                    "ok": False,
                    "message": str(exc),
                }, ensure_ascii=False).encode("utf-8")
                self.send_response(400)
                self.send_header(
                    "Content-Type",
                    "application/json; charset=utf-8",
                )
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)

        def log_message(self, _format, *_args):
            return

    def _run_monitor_tv_http_server():
        # TV traffic has its own endpoint. It never shares the authenticated
        # two-PC relay port, so simultaneous PC1/PC2 and TV access cannot bind
        # to the same socket or disturb IEC-104 sessions.
        bind_ip = _local_scada_ip() or "127.0.0.1"
        server = ThreadingHTTPServer((bind_ip, MONITOR_TV_PORT), MonitorTVRequestHandler)
        _communication_log(bind_ip, "MONITOR_TV_SERVER", f"listening={bind_ip}:{MONITOR_TV_PORT}")
        server.serve_forever()

    class RealtimeRelayRequestHandler(BaseHTTPRequestHandler):
        """Authenticated realtime/config relay, reachable only by the paired PC."""
        def do_GET(self):
            config = _communication_config()
            allowed_peer = _parallel_peer_ip()
            expected_token = str(config.get("relay_token", ""))
            remote_ip = str(self.client_address[0])
            supplied_token = str(self.headers.get("X-SCADA-Relay-Token", ""))
            path = urlparse(self.path).path.rstrip("/")
            if remote_ip != allowed_peer or not expected_token or supplied_token != expected_token:
                body = b"Forbidden"
                self.send_response(403)
                self.send_header("Content-Type", "text/plain; charset=utf-8")
            elif path == "/RealtimeSnapshot.json":
                body = json.dumps(
                    _full_realtime_relay_payload(),
                    ensure_ascii=False,
                    separators=(",", ":")
                ).encode("utf-8")
                self.send_response(200)
                self.send_header("Content-Type", "application/json; charset=utf-8")
                self.send_header("Cache-Control", "no-store")
            elif path == "/ConfigSyncManifest.json":
                body = json.dumps(
                    _config_sync_manifest(),
                    ensure_ascii=False,
                    separators=(",", ":")
                ).encode("utf-8")
                self.send_response(200)
                self.send_header("Content-Type", "application/json; charset=utf-8")
                self.send_header("Cache-Control", "no-store")
            elif path == "/ConfigSync.json":
                body = json.dumps(
                    _config_sync_snapshot(),
                    ensure_ascii=False,
                    separators=(",", ":")
                ).encode("utf-8")
                self.send_response(200)
                self.send_header("Content-Type", "application/json; charset=utf-8")
                self.send_header("Cache-Control", "no-store")
            else:
                body = b"Not Found"
                self.send_response(404)
                self.send_header("Content-Type", "text/plain; charset=utf-8")
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)

        def log_message(self, _format, *_args):
            return

    def _run_realtime_relay_server():
        config = _communication_config()
        local_ip = _local_scada_ip()
        port = int(config.get("relay_port", 5001))
        if not local_ip:
            _communication_log("LOCAL", "RELAY_SERVER_ERROR", "SCADA IP .149/.150 not found")
            return
        server = ThreadingHTTPServer((local_ip, port), RealtimeRelayRequestHandler)
        _communication_log(local_ip, "RELAY_SERVER", f"listening={local_ip}:{port}")
        server.serve_forever()

    def start_monitor_tv_json_writer():
        threading.Thread(
            target=_monitor_tv_json_writer,
            daemon=True,
            name="MonitorTv-JSON",
        ).start()
        threading.Thread(
            target=_run_monitor_tv_http_server,
            daemon=True,
            name="MonitorTv-HTTP",
        ).start()
        config = _communication_config()
        local_ip = _local_scada_ip()
        paired_ips = {str(config.get("master_ip", "")), str(config.get("peer_ip", ""))}
        # Both PCs host the authenticated relay: PC2 still pulls realtime
        # telemetry from PC1, while configuration snapshots flow both ways.
        if local_ip in paired_ips:
            threading.Thread(
                target=_run_realtime_relay_server,
                daemon=True,
                name="SCADA-Realtime-Relay",
            ).start()
            threading.Thread(
                target=_config_sync_worker,
                daemon=True,
                name="SCADA-Config-Sync",
            ).start()

except Exception as _monitor_tv_import_error:
    MONITOR_TV_AVAILABLE = False

    def start_monitor_tv_json_writer():
        print(f"Monitor TV JSON disabled: {_monitor_tv_import_error}")



