def run_engineering_qc():
    """Deterministic offline QC for authoritative RTU1 routing and scaling."""
    failures = []
    tests = [
        (("W1_Ia", 143), 13.0845),
        (("W2_Ia", 160), 14.64),
        (("W1_Uab", 27689), 6.084008771120027),
        (("W2_Uab", 27638), 6.072802716465576),
        (("W1_P", -122), -116.0727538788),
        (("W1_Q", -89), -84.6760253706),
        (("W2_P", 244), 232.1455077576),
        (("W2_Q", -26), -24.7368164004),
    ]
    with SETTING_LOCK:
        rows = {r.get("Physical_Name"): r for r in SETTING_REGISTRY
                if r.get("Device_Addr") == "10.100.163.1"}
    expected_keys = {
        "W1_Ia": (257, 16385), "W1_Uab": (257, 16388),
        "W1_Ubc": (257, 16389), "W1_Uca": (257, 16390),
        "W1_P": (257, 16391), "W1_Q": (257, 16392), "W1_f": (257, 16393),
        "W2_Ia": (513, 16385), "W2_Uab": (513, 16388),
        "W2_Ubc": (513, 16389), "W2_Uca": (513, 16390),
        "W2_P": (513, 16391), "W2_Q": (513, 16392), "W2_f": (513, 16393),
    }
    for tag, key in expected_keys.items():
        row = rows.get(tag)
        if row is None or (row.get("ASDU_INT"), row.get("IOA_INT")) != key:
            failures.append(f"{tag}: mapping {key} not present")
    for (tag, raw), expected in tests:
        row = rows.get(tag)
        if row is None:
            failures.append(f"{tag}: missing formula row")
            continue
        try:
            actual = _calculate_formula(raw, row, {})
            if not math.isclose(actual, expected, rel_tol=1e-8, abs_tol=1e-8):
                failures.append(f"{tag}: {actual} != {expected}")
        except Exception as exc:
            failures.append(f"{tag}: formula error {exc}")
    if failures:
        print("[ENGINEERING QC] FAILED")
        for failure in failures:
            print(" -", failure)
        return False
    print("[ENGINEERING QC] PASS - RTU1 address routing and scaling formulas verified")
    return True

