# STARTUP VALIDATION
# ==============================================================================
def validate_setting_files():
    """Validate CSV schema and detect only real address/variable conflicts."""
    required = set(SETTING_COLUMNS) - {"Add_Offset"}  # optional for old CSVs
    problems = []
    warnings = []
    try:
        files = sorted(
            f for f in os.listdir(APP_DIR)
            if f.startswith("ListSetting ")
            and f.lower().endswith(".csv")
            and not re.search(r"_(fix|backup|bak|old)\.csv$", f, re.IGNORECASE)
        )
    except Exception:
        files = []

    protocol_keys = {}
    variable_keys = {}

    for filename in files:
        path = os.path.join(APP_DIR, filename)
        try:
            with open(path, "r", newline="", encoding="utf-8-sig") as f:
                reader = csv.DictReader(f)
                headers = set(reader.fieldnames or [])
                missing = required - headers
                if missing:
                    problems.append(f"{filename}: missing {sorted(missing)}")
                    continue

                for line_no, row in enumerate(reader, 2):
                    ip = _norm_text(row.get("Device_Addr"))
                    physical = _norm_text(row.get("Physical_Name"))
                    if not ip or not physical:
                        problems.append(f"{filename}:{line_no}: Device_Addr/Physical_Name kosong")
                        continue
                    try:
                        asdu = int(float(_norm_text(row.get("ASDU"))))
                        ioa_text = _norm_text(row.get("IOA"))
                        ioa = int(float(ioa_text)) if ioa_text else None
                    except Exception:
                        problems.append(f"{filename}:{line_no}: ASDU/IOA bukan angka")
                        continue

                    if ioa is not None:
                        key = (ip, asdu, ioa)
                        previous = protocol_keys.get(key)
                        if previous is None:
                            protocol_keys[key] = physical
                        elif previous.lower() != physical.lower():
                            warnings.append(
                                f"{filename}:{line_no}: ASDU/IOA collision {key}: "
                                f"{previous} vs {physical}; runtime uses the last active row"
                            )

                    vkey = (ip, physical.lower())
                    current = (asdu, ioa)
                    previous = variable_keys.get(vkey)
                    if previous is None:
                        variable_keys[vkey] = current
                    elif previous != current:
                        warnings.append(
                            f"{filename}:{line_no}: variable {ip}/{physical} has "
                            f"multiple ASDU/IOA definitions {previous} and {current}"
                        )
        except Exception as exc:
            problems.append(f"{filename}: {exc}")

    if problems:
        print("[CSV VALIDATION] FAILED")
        for problem in problems:
            print(" -", problem)
        return False

    if warnings:
        print("[CSV VALIDATION] WARNINGS")
        for warning in warnings:
            print(" -", warning)
    print(f"[CSV VALIDATION] OK - {len(files)} active ListSetting files loaded")
    return True

validate_setting_files()
run_engineering_qc()

